def initialize_sqlite_index_store(db_path):
    """Create the non-authoritative SQLite indexing store for migration stage 1.

    This does not import, modify, or replace existing JSON records. Callers may
    use it to prepare indexed tables while JSON remains the authoritative store.
    """
    folder = os.path.dirname(os.path.abspath(db_path))
    if folder:
        os.makedirs(folder, exist_ok=True)
    conn = sqlite3.connect(db_path)
    try:
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA foreign_keys=ON")
        conn.executescript(
            "CREATE TABLE IF NOT EXISTS customer_index ("
            " customer_key TEXT NOT NULL, customer_name TEXT NOT NULL, "
            " mbal_id TEXT, phone_digits TEXT, whatsapp_username TEXT);"
            "CREATE INDEX IF NOT EXISTS idx_customer_index_key "
            " ON customer_index(customer_key);"
            "CREATE INDEX IF NOT EXISTS idx_customer_index_mbal "
            " ON customer_index(mbal_id);"
            "CREATE INDEX IF NOT EXISTS idx_customer_index_phone "
            " ON customer_index(phone_digits);"
            "CREATE INDEX IF NOT EXISTS idx_customer_index_username "
            " ON customer_index(whatsapp_username);"
            "CREATE TABLE IF NOT EXISTS transaction_index ("
            " transaction_key TEXT NOT NULL, customer_key TEXT, "
            " platform_key TEXT, platform_id TEXT, occurred_at TEXT, "
            " status TEXT);"
            "CREATE INDEX IF NOT EXISTS idx_transaction_customer_date "
            " ON transaction_index(customer_key, occurred_at);"
            "CREATE INDEX IF NOT EXISTS idx_transaction_platform_id "
            " ON transaction_index(platform_key, platform_id);"
            "CREATE INDEX IF NOT EXISTS idx_transaction_date_status "
            " ON transaction_index(occurred_at, status);"
        )
        conn.commit()
    finally:
        conn.close()
    return db_path

def sync_sqlite_mirror(db_path, data):
    """Atomically mirror current business data and searchable records into SQLite.

    JSON remains the compatibility/rollback source during this migration stage.
    SQLite stores a complete snapshot plus indexed per-record rows; no business
    records are deleted from JSON and no app logic reads from SQLite yet.
    """
    folder = os.path.dirname(os.path.abspath(db_path))
    if folder:
        os.makedirs(folder, exist_ok=True)
    conn = sqlite3.connect(db_path, timeout=20)
    try:
        conn.execute("PRAGMA journal_mode=WAL")
        conn.execute("PRAGMA foreign_keys=ON")
        conn.execute("PRAGMA busy_timeout=20000")
        conn.executescript("""
            CREATE TABLE IF NOT EXISTS app_state (
                singleton_id INTEGER PRIMARY KEY CHECK(singleton_id=1),
                schema_version INTEGER NOT NULL,
                payload_json TEXT NOT NULL,
                updated_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS business_records (
                collection TEXT NOT NULL,
                record_key TEXT NOT NULL,
                customer_key TEXT,
                platform_key TEXT,
                platform_id TEXT,
                occurred_at TEXT,
                status TEXT,
                payload_json TEXT NOT NULL,
                PRIMARY KEY(collection, record_key)
            );
            CREATE INDEX IF NOT EXISTS idx_records_customer_date
                ON business_records(collection, customer_key, occurred_at);
            CREATE INDEX IF NOT EXISTS idx_records_platform_id
                ON business_records(collection, platform_key, platform_id);
            CREATE INDEX IF NOT EXISTS idx_records_date_status
                ON business_records(collection, occurred_at, status);
            CREATE INDEX IF NOT EXISTS idx_records_customer
                ON business_records(collection, customer_key);
            CREATE UNIQUE INDEX IF NOT EXISTS idx_unique_customer_mbal_id
                ON business_records(platform_id)
                WHERE collection='customers' AND platform_key='CUSTOMER'
                  AND platform_id IS NOT NULL AND platform_id<>'';
        """)
        payload = json.dumps(data, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
        now = datetime.now().isoformat(timespec="seconds")
        # Build rows before opening the write transaction, so malformed data fails safely.
        rows = []
        list_collections = (
            "transactions", "purchases", "finance", "rate_history", "adjustments",
            "obligations", "customer_payments", "asset_register", "audit",
            "tax_threshold_history", "referral_agreements", "referrals", "rewards_ledger",
            "referral_disbursements", "referral_redemptions", "referral_vested_carryovers",
            "reward_disbursements"
        )
        for collection in list_collections:
            records = data.get(collection, [])
            if not isinstance(records, list):
                continue
            for i, rec in enumerate(records):
                if not isinstance(rec, dict):
                    continue
                key = str(rec.get("record_id") or rec.get("id") or f"{collection}:{i}")
                customer = rec.get("customer") or rec.get("customer_name") or rec.get("customer_key")
                platform = rec.get("platform") or rec.get("platform_key")
                platform_id = rec.get("platform_id") or rec.get("customer_id")
                occurred = (rec.get("timestamp") or rec.get("date") or rec.get("created_at")
                            or rec.get("datetime") or rec.get("time"))
                status = rec.get("status") or rec.get("state")
                rows.append((collection, key, str(customer) if customer is not None else None,
                             str(platform) if platform is not None else None,
                             str(platform_id) if platform_id is not None else None,
                             str(occurred) if occurred is not None else None,
                             str(status) if status is not None else None,
                             json.dumps(rec, ensure_ascii=False, allow_nan=False, separators=(",", ":"))))
        # Customer records use the customer key as their stable searchable key.
        customers = data.get("customers", {})
        if isinstance(customers, dict):
            for name, rec in customers.items():
                if not isinstance(rec, dict):
                    continue
                phone = re.sub(r"\D", "", str(rec.get("phone") or rec.get("whatsapp") or ""))
                username = str(rec.get("whatsapp_username") or rec.get("username") or "").strip().casefold()
                customer_json = json.dumps(rec, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
                # Keep customer search tokens in the same indexed record table.
                rows.append(("customers", str(rec.get("record_id") or name), str(name), "CUSTOMER",
                             str(rec.get("mbal_id") or "") or None, str(rec.get("created_at") or "") or None,
                             ("phone:" + phone + "|username:" + username), customer_json))
        conn.execute("BEGIN IMMEDIATE")
        conn.execute("""INSERT INTO app_state(singleton_id,schema_version,payload_json,updated_at)
                        VALUES(1,2,?,?) ON CONFLICT(singleton_id) DO UPDATE SET
                        schema_version=excluded.schema_version,
                        payload_json=excluded.payload_json, updated_at=excluded.updated_at""",
                     (payload, now))
        conn.execute("DELETE FROM business_records")
        conn.executemany("""INSERT INTO business_records
            (collection,record_key,customer_key,platform_key,platform_id,occurred_at,status,payload_json)
            VALUES(?,?,?,?,?,?,?,?)""", rows)
        conn.commit()
    except Exception:
        conn.rollback()
        raise
    finally:
        conn.close()
    return {"collections_indexed": len(rows), "updated_at": now}


