        self.data.setdefault("finance", [])
        self.data.setdefault("asset_register", [])
        self.data["global"].setdefault("opening_balance", 0.0)
        self.data.setdefault("customers", {})
        self.data.setdefault("adjustments", [])
        self.data.setdefault("audit", [])
        self.data.setdefault("obligations", [])
        # V40.87: remove legacy SMS/birthday feature data; these features are no longer supported.
        _removed_sms_birthday_data = False
