    def _backup_files(self):
        folder=self.backup_directory()
        paths=[os.path.join(folder,n) for n in os.listdir(folder)
               if n.startswith("brownian_") and n.endswith(".json") and os.path.isfile(os.path.join(folder,n))]
        return sorted(paths,key=lambda p:(os.path.getmtime(p),os.path.basename(p)),reverse=True)

    def _prune_backups(self):
        """Keep the newest two files in each backup category independently.

        Categories are manual, automatic, and safety/other (including scheduled
        email tests and pre-operation snapshots). Files are sorted newest-first
        by _backup_files(); pruning only removes entries beyond each category's
        two newest files. A newly created backup is written before pruning runs.
        """
        groups={"manual":[],"auto":[],"safety":[]}
        for path in self._backup_files():
            name=os.path.basename(path)
            if name.startswith("brownian_manual_"):
                groups["manual"].append(path)
            elif name.startswith("brownian_auto_"):
                groups["auto"].append(path)
            else:
                groups["safety"].append(path)
        for group in ("manual","auto","safety"):
            for path in groups[group][2:]:
                try:
                    os.remove(path)
                except OSError:
                    # Retention is best-effort if Android storage refuses deletion.
                    pass

    def backup_directory(self):
        # Use the administrator-selected backup path first, then safe defaults.
        configured = str(self.data.get("global", {}).get("backup_storage_path", "") or "").strip()
        folders = ([os.path.expanduser(configured)] if configured else []) + [
            "/storage/emulated/0/Download/Mr Brownian Backups",
            os.path.join(self.user_data_dir,"Mr Brownian Backups")]
        errors=[]
        for folder in folders:
            try:
                os.makedirs(folder,exist_ok=True)
                with tempfile.NamedTemporaryFile(dir=folder,delete=True) as f:f.write(b"ok")
                return folder
            except Exception as exc: errors.append(f"{folder}: {exc}")
        if configured:
            raise OSError("Selected storage path is not writable. Check the path and Android storage permissions. " + " | ".join(errors))
        raise OSError("No writable backup folder")

    def create_backup(self, reason="manual", show_result=True):
        # Copy the complete active JsonStore file, not a reconstructed subset.
        try:
            self.save()
            source=self._database_path
            if not os.path.isfile(source):raise FileNotFoundError(source)
            folder=self.backup_directory()
            stamp=datetime.now().strftime("%Y%m%d_%H%M%S_%f")
            dest=os.path.join(folder,f"brownian_{reason}_{stamp}.json")
            with open(source,"rb") as f: raw=f.read()
            payload=json.loads(raw.decode("utf-8"))
            if not isinstance(payload,dict) or "settings" not in payload:raise ValueError("Unrecognized business database")
            fd,tmp=tempfile.mkstemp(prefix=".backup_",dir=folder)
            try:
                with os.fdopen(fd,"wb") as f:f.write(raw);f.flush();os.fsync(f.fileno())
                os.replace(tmp,dest)
            finally:
                if os.path.exists(tmp):os.unlink(tmp)
            self._prune_backups()
            if show_result:self.popup("Backup Saved",dest)
            return dest
        except Exception as exc:
            if show_result:self.popup("Backup Failed",str(exc))
            return None

    def safe_inventory_rebuild(self):
        self.ask("REBUILD INVENTORY","Recalculate inventory from surviving purchases, sales and Goods adjustments? Backup will be made first.",lambda:self._safe_inventory_rebuild_final())

    def _safe_inventory_rebuild_final(self):
        return self.inventory_edit(lambda: self._safe_inventory_rebuild_final_impl())()

    def _safe_inventory_rebuild_final_impl(self):
        if not self.create_backup("before_inventory_rebuild",False):return self.popup("Cancelled","Backup failed")
        self.rebuild_inventory_costs();self.audit("rebuild","inventory","all");self.save()
        self.popup("Inventory Rebuilt","Inventory recalculated from surviving records. Compare POPPO balance before any manual correction.")

