    def total_assets(self):
        return self.cash_balance()+self.inventory_summary()[1]

    def customer_balance(self, customer):
        if not customer: return 0.0
        bal=0.0
        for x in self.data.get("transactions",[]):
            if x.get("customer","").strip().lower()==customer.strip().lower(): bal += float(x.get("balance", self.num(x.get("sell")) - self.num(x.get("collected", x.get("sell", 0))) - self.num(x.get("referral_redemption_value"))))
        for x in self.data.get("adjustments",[]):
            if x.get("customer","").strip().lower()==customer.strip().lower(): bal += float(x.get("balance_effect",0))
        for x in self.data.get("customer_payments",[]):
            if x.get("customer","").strip().lower()==customer.strip().lower(): bal -= float(x.get("amount",0))
        return round(bal,2)

    def inventory_edit(self, callback):
        """Cancel an inventory-changing UI action if replay or persistence fails."""
        def guarded(*args, **kwargs):
            import copy
            original = self.data
            snapshot = copy.deepcopy(original)
            records = {(key, rec.get("record_id")): rec
                       for key, values in original.items() if isinstance(values, list)
                       for rec in values if isinstance(rec, dict) and rec.get("record_id")}
            old_platform = self.current_platform
            try:
                return callback(*args, **kwargs)
            except Exception as exc:
                for key, values in snapshot.items():
                    if isinstance(values, list):
                        for index, rec in enumerate(values):
                            if isinstance(rec, dict):
                                existing = records.get((key, rec.get("record_id")))
                                if existing is not None:
                                    existing.clear()
                                    existing.update(rec)
                                    values[index] = existing
                original.clear()
                original.update(snapshot)
                self.data = original
                self.current_platform = old_platform
                return self.popup("Change Cancelled", str(exc))
        return guarded

    def rebuild_inventory_costs(self):
        """Replay every stock movement chronologically; apply only a complete replay.

        Historical linked generation sessions describe existing movements and are
        never deducted again. At equal timestamps, paid/opening acquisitions are
        available first, then investments, generated receipts, and other outflows.
        """
        events = []
        updates = []
        lots = []
        generation_costs = {}
        generation_records = {}

        def active(rec):
            return not any(rec.get(k) for k in ("deleted", "cancelled", "reversed"))

        def add(rec, kind, priority, qty=None, owner=None):
            events.append((str(rec.get("date", "")), priority, len(events), kind, rec, qty, owner))

        for rec in self.data.get("purchases", []):
            if active(rec):
                priority = 2 if rec.get("generation_id") else 0
                add(rec, "acquisition", priority)
            else:
                updates.append((rec, {"remaining_qty": 0.0, "remaining_cost": 0.0}))
        for rec in self.data.get("transactions", []):
            if active(rec):
                add(rec, "sale", 3)
        for rec in self.data.get("finance", []):
            if active(rec) and str(rec.get("payment_method", "")).lower() == "Goods" and rec.get("kind") == "expense" and self.num(rec.get("goods_qty")) > 0:
                add(rec, "legacy_goods_expense", 3)
        for rec in self.data.get("goods_adjustments", []):
            if active(rec) and rec.get("type") == "Goods gifted" and self.num(rec.get("qty")) > 0:
                add(rec, "goods_adjustment", 3)
        for rec in self.data.get("goods_generations", []):
            # Linked sessions are audit views of coin_adjustments and purchases.
            if not active(rec) or rec.get("linked_movements") or rec.get("status") == "historical_linked":
                continue
            rid = rec.get("record_id")
            generation_records[rid] = rec
            generation_costs[rid] = 0.0
            extra = [r for r in rec.get("investments", []) if active(r)]
            initial = self.num(rec.get("invested_qty")) - sum(self.num(r.get("qty")) for r in extra)
            if initial < -1e-7:
                raise ValueError("Generation investment history exceeds its total quantity.")
            if initial > 1e-7:
                add(rec, "investment", 1, initial, rid)
            for investment in extra:
                if self.num(investment.get("qty")) > 0:
                    movement = dict(investment, platform=rec.get("platform"))
                    add(movement, "investment", 1, self.num(investment.get("qty")), rid)
        for collection in ("reward_disbursements", "referral_disbursements"):
            for rec in self.data.get(collection, []):
                if active(rec) and (collection != "referral_disbursements" or rec.get("posting_status") == "posted"):
                    add(rec, "reward", 3)

        def consume(platform, quantity, date):
            quantity = float(quantity)
            if not math.isfinite(quantity) or quantity < 0:
                raise ValueError("Invalid inventory outflow quantity.")
            eligible = [lot for lot in lots if lot["platform"] == platform and lot["qty"] > 0]
            available = sum(lot["qty"] for lot in eligible)
            if available + 1e-7 < quantity:
                raise ValueError(f"Inventory rebuild blocked: {platform} on {date}: need {quantity:,.6f}, available {available:,.6f}. No rebuilt values were applied.")
            remaining = quantity
            cost = 0.0
            for lot in eligible:
                if remaining <= 1e-9:
                    break
                take = min(lot["qty"], remaining)
                part = lot["cost"] * take / lot["qty"]
                lot["qty"] = max(0.0, lot["qty"] - take)
                lot["cost"] = max(0.0, lot["cost"] - part)
                cost += part
                remaining -= take
            return cost

        for date, _, _, kind, rec, quantity, owner in sorted(events, key=lambda item: item[:3]):
            platform = rec.get("platform", "")
            if kind == "acquisition":
                qty = float(rec.get("qty", 0))
                cost = float(rec.get("cost", 0))
                generation_id = rec.get("generation_id")
                if generation_id in generation_records:
                    generation = generation_records[generation_id]
                    receipts = generation.get("receipts", [])
                    first = next((r for r in receipts if active(r)), None)
                    is_first = first is not None and first.get("record_id") == rec.get("record_id")
                    cost = generation_costs[generation_id] if is_first else 0.0
                    updates.append((rec, {"cost": cost}))
                    for receipt in receipts:
                        if receipt.get("record_id") == rec.get("record_id"):
                            updates.append((receipt, {"cost": cost}))
                if not math.isfinite(qty) or not math.isfinite(cost) or qty < 0 or cost < 0:
                    raise ValueError("Invalid acquisition quantity or cost; inventory rebuild cancelled.")
                lots.append({"record": rec, "platform": platform, "qty": qty, "cost": cost})
            elif kind == "sale":
                parts = self.transaction_allocations(rec)
                if not parts:
                    parts = [{"platform": platform, "qty": self.num(rec.get("qty"))}]
                cost = sum(consume(part["platform"], part["qty"], date) for part in parts)
                sell = self.num(rec.get("sell"))
                updates.append((rec, {"cost": cost, "profit": sell - cost,
                                     "margin": (sell - cost) / sell * 100 if sell else 0.0,
                                     "fifo_rebuild_ok": True}))
            elif kind == "investment":
                generation_costs[owner] += consume(platform, quantity, date)
            else:
                qty = rec.get("goods_qty", 0) if kind == "legacy_goods_expense" else rec.get("qty", 0)
                cost = consume(platform, qty, date)
                field = "fifo_cost" if kind == "reward" else "amount" if kind == "legacy_goods_expense" else "cost"
                updates.append((rec, {field: cost}))

        for rid, generation in generation_records.items():
            updates.append((generation, {"invested_cost": generation_costs[rid]}))
        for loss in self.data.get("generation_losses", []):
            if loss.get("generation_id") in generation_costs:
                updates.append((loss, {"cost": generation_costs[loss["generation_id"]]}))
        for lot in lots:
            updates.append((lot["record"], {"remaining_qty": lot["qty"], "remaining_cost": lot["cost"]}))
        for rec, fields in updates:
            rec.update(fields)

    def reconcile_business_records(self, show_result=True):
        return self.inventory_edit(lambda: self.reconcile_business_records_impl(show_result))()

    def reconcile_business_records_impl(self, show_result=True):
        """Reconcile legacy derived records against surviving source records.
        Removes identifiable stale auto-generated ledger/inventory rows while
        preserving standalone manual finance entries and opening balances."""
        transactions=self.data.get("transactions",[])
        purchases=self.data.get("purchases",[])
        finance=self.data.get("finance",[])

        txids={str(x.get("record_id")) for x in transactions if x.get("record_id")}
        purchaseids={str(x.get("record_id")) for x in purchases if x.get("record_id")}

        # Build conservative signatures for surviving source records.  This is
        # used for legacy rows created before record_id/ref_id was introduced.
        def money(v):
            try: return round(float(str(v).replace(",","").replace("₦","").strip() or 0),2)
            except: return 0.0
        def qty(v):
            try: return round(float(str(v).replace(",","").strip() or 0),4)
            except: return 0.0
        def day(v):
            s=str(v or "")
            return s[:10]

        live_sale_sigs=set()
        for t in transactions:
            live_sale_sigs.add((day(t.get("date")),str(t.get("platform","")).upper(),
                                money(t.get("collected",t.get("sell",0))),
                                qty(t.get("qty",0))))
        live_acq_sigs=set()
        for p in purchases:
            live_acq_sigs.add((day(p.get("date")),str(p.get("platform","")).upper(),
                               money(p.get("cost",p.get("amount",0))),
                               qty(p.get("qty",0))))

        kept=[]; removed=[]
        for f in finance:
            cat=str(f.get("category",""))
            ref=str(f.get("ref_id") or "")
            auto=bool(f.get("auto") or f.get("source_record") or ref or cat in
                      ("Customer Payment","Goods Purchase","Withdrawal Acquisition"))
            orphan=False; reason=""

            if cat=="Customer Payment":
                if ref:
                    orphan=ref not in txids; reason="deleted sale"
                elif auto:
                    sig=(day(f.get("date")),str(f.get("platform","")).upper(),
                         money(f.get("amount",0)),qty(f.get("qty",0)))
                    # Legacy ledgers often omitted quantity. Match date/platform/amount
                    # when quantity is unavailable.
                    if sig[3]:
                        orphan=sig not in live_sale_sigs
                    else:
                        orphan=not any(a==sig[0] and b==sig[1] and c==sig[2]
                                       for a,b,c,d in live_sale_sigs)
                    reason="legacy deleted sale"
            elif cat in ("Goods Purchase","Withdrawal Acquisition"):
                if ref:
                    orphan=ref not in purchaseids; reason="deleted acquisition"
                elif auto:
                    sig=(day(f.get("date")),str(f.get("platform","")).upper(),
                         money(f.get("amount",0)),qty(f.get("qty",0)))
                    if sig[3]:
                        orphan=sig not in live_acq_sigs
                    else:
                        orphan=not any(a==sig[0] and b==sig[1] and c==sig[2]
                                       for a,b,c,d in live_acq_sigs)
                    reason="legacy deleted acquisition"

            if orphan:
                removed.append((f,reason))
            else:
                kept.append(f)

        self.data["finance"]=kept

        # Inventory/FIFO is derived again from surviving acquisitions and sales,
        # so stale lots/cost effects from deleted records cannot remain.
        self.rebuild_inventory_costs()
        self.save()

        cash_effect=sum(money(f.get("amount",0)) *
                        (1 if str(f.get("type","")).lower()=="income" else -1)
                        for f,_ in removed)

        if show_result:
            if removed:
                details="\n".join(
                    f"{i}. {f.get('date','')} | {f.get('category','Record')} | "
                    f"₦{money(f.get('amount',0)):,.2f} | {reason}"
                    for i,(f,reason) in enumerate(removed[:8],1)
                )
                extra="" if len(removed)<=8 else f"\n...and {len(removed)-8} more."
                self.popup("Reconciliation Complete",
                    f"Removed {len(removed)} identifiable orphaned derived record(s).\n"
                    f"Net ledger effect removed: ₦{cash_effect:,.2f}.\n\n"
                    f"{details}{extra}\n\nBalances and FIFO inventory were rebuilt.")
            else:
                self.popup("No Identifiable Orphans",
                    "No orphaned auto-linked or legacy-derived ledger records could be "
                    "identified safely. No standalone/manual finance records were deleted.")
        return len(removed)

    def share_file(self, path, mime=None, chooser_title="Share file"):
        """Share a generated file on Android; keeps Excel behavior and also supports receipt JPGs."""
        try:
            from jnius import autoclass, cast
            Intent=autoclass('android.content.Intent'); Uri=autoclass('android.net.Uri'); File=autoclass('java.io.File')
            PythonActivity=autoclass('org.kivy.android.PythonActivity')
            try:
                StrictMode=autoclass('android.os.StrictMode')
                StrictMode.setVmPolicy(StrictMode.VmPolicy.Builder().build())
            except Exception:
                pass
            if not mime:
                mime='image/png' if str(path).lower().endswith('.png') else 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            intent=Intent(); intent.setAction(Intent.ACTION_SEND); intent.setType(mime)
            intent.putExtra(Intent.EXTRA_STREAM, cast('android.os.Parcelable', Uri.fromFile(File(path))))
            intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            PythonActivity.mActivity.startActivity(Intent.createChooser(intent,chooser_title))
        except Exception:
            self.popup("File Saved", path)

    def clear_root(self):
        if self.root:
            self.root.clear_widgets()

    def on_stop(self):
        """Release page keyboard callbacks before the Android window is closed."""
        for name in ("_splash_start_event", "_splash_home_event", "_bank_poll_timer", "_messaging_pending_timer", "_backup_scheduler_event"):
            event = getattr(self, name, None)
            if event is not None:
                event.cancel()
                setattr(self, name, None)
        keyboard = getattr(self, "_retail_keyboard", None)
        try:
            if keyboard:
                keyboard["deactivate"]()
        finally:
            Window.unbind(on_touch_down=self._backup_idle_activity)
            Window.unbind(on_keyboard=self._on_android_back,
                          on_touch_down=self._swipe_touch_down, on_touch_up=self._swipe_touch_up)

