    def header(self, text):
        lab = Label(
            text=str(text).upper(), font_size="24sp", bold=True, color=self.TEXT,
            halign="center", valign="middle", size_hint_y=None, height=dp(78)
        )
        lab.bind(size=lambda obj, val: setattr(obj, "text_size", (val[0], None)))
        return lab

    def section_label(self, text):
        lab = Label(
            text=str(text).upper(), bold=True, color=self.SUBTEXT, font_size="14sp",
            halign="left", valign="middle", size_hint_y=None, height=dp(36)
        )
        lab.bind(size=lambda obj, val: setattr(obj, "text_size", (val[0], None)))
        return lab

    def card(self, height=90, color=None, padding=14):
        box = BoxLayout(
            orientation="vertical", size_hint_y=None, height=dp(height),
            padding=dp(padding), spacing=dp(4)
        )
        rgba = color or self.PANEL
        with box.canvas.before:
            Color(*rgba)
            rect = RoundedRectangle(pos=box.pos, size=box.size, radius=[dp(20)])
        box.bind(pos=lambda obj,val: setattr(rect,"pos",val),
                 size=lambda obj,val: setattr(rect,"size",val))
        return box

    def nav_button(self, text, fn, kind="primary"):
        text = str(text).replace("/n", ": ").replace("\\n", ": ")
        icon,text=self._split_icon(text)
        palette = {
            "primary": self.PRIMARY, "success": self.SUCCESS,
            "accent": self.ACCENT, "danger": self.DANGER,
            "muted": self.MUTED, "purple": self.PURPLE
        }
        b = Button(
            text=text, size_hint_y=None, height=dp(58),
            background_normal="", background_down="", background_color=(0,0,0,0),
            color=get_color_from_hex("#FFFFFF"), font_size="17sp", bold=True
        )
        with b.canvas.before:
            Color(*palette.get(kind, self.PRIMARY))
            rect = RoundedRectangle(pos=b.pos, size=b.size, radius=[dp(18)])
        b.bind(pos=lambda obj,val: setattr(rect,"pos",val), size=lambda obj,val: setattr(rect,"size",val))
        b.bind(on_release=lambda *_: fn())
        b.halign = "center"; b.valign = "middle"
        b.bind(size=lambda obj,val: setattr(obj, "text_size", (max(val[0]-dp(64 if icon else 24),dp(40)), max(val[1]-dp(8),dp(20)))))
        if icon:self._decorate_icon(b,icon,24,True)
        return b
    def style_input(self, ti):
        # Numeric fields deliberately allow commas/currency symbols to be pasted; parsing is sanitized by num().
        if getattr(ti, "input_filter", None) in ("float", "int"):
            ti.input_filter = None
        ti.background_normal = ""
        ti.background_active = ""
        ti.background_color = self.INPUT_BG
        ti.foreground_color = self.TEXT
        ti.hint_text_color = self.SUBTEXT
        ti.cursor_color = self.PRIMARY
        ti.selection_color = get_color_from_hex("#93C5FD")
        ti.font_size = "18sp"
        ti.padding = [dp(16),dp(14),dp(16),dp(14)]
        return ti

    def normalize_whatsapp_number(self, number):
        """Normalize phone/WhatsApp numbers regardless of spaces, hyphens or brackets.

        Formatting characters are ignored everywhere this helper is used. Nigerian
        local numbers beginning with 0 are converted to the international 234 form.
        """
        digits = re.sub(r"\D", "", str(number or ""))
        if digits.startswith("00"):
            digits = digits[2:]
        if digits.startswith("0") and len(digits) >= 10:
            digits = "234" + digits[1:]
        return digits

    def open_contact_uri(self, uri, title="Contact"):
        """Open Android dialer/WhatsApp link without requesting direct-call permission."""
        try:
            from kivy.utils import platform as kivy_platform
            if kivy_platform == "android":
                from jnius import autoclass
                Intent=autoclass("android.content.Intent")
                Uri=autoclass("android.net.Uri")
                activity=autoclass("org.kivy.android.PythonActivity").mActivity
                action=Intent.ACTION_DIAL if uri.startswith("tel:") else Intent.ACTION_VIEW
                intent=Intent(action,Uri.parse(uri))
                activity.startActivity(intent)
                return
        except Exception:
            pass
        try:
            webbrowser.open(uri)
        except Exception as e:
            self.popup(title,f"Unable to open this contact action.\n{e}")

    def call_number(self, number):
        digits=re.sub(r"\D","",str(number or ""))
        if not digits:
            self.popup("Phone","No valid phone number is available.");return
        self.open_contact_uri("tel:"+digits,"Phone")

    def whatsapp_number(self, number):
        digits=self.normalize_whatsapp_number(number)
        if not digits:
            self.popup("WhatsApp","No valid WhatsApp number is available.");return
        self.open_contact_uri("https://wa.me/"+digits,"WhatsApp")

    @staticmethod
    def whatsapp_monospace(text):
        text=str(text or "")
        # WhatsApp interprets *bold* only in normal proportional text.
        # Remove legacy full-message code fences; preserve inline emphasis.
        if text.startswith("```\n") and text.endswith("\n```"):
            text=text[4:-4]
        return text

    def whatsapp_prefill(self, number, text):
        """Open a customer's WhatsApp chat with customer-safe report already prefilled."""
        digits=self.normalize_whatsapp_number(number)
        text=self.whatsapp_monospace(text)
        Clipboard.copy(str(text))
        if not digits:
            self.popup("Report Copied","Report copied to clipboard. No valid WhatsApp number is available for this customer.")
            return
        try:
            from urllib.parse import quote
            self.open_contact_uri("https://wa.me/"+digits+"?text="+quote(str(text)),"WhatsApp")
        except Exception:
            self.popup("Report Copied","Report copied to clipboard. Paste it into WhatsApp.")

    def customer_trading_balance(self, customer, before=""):
        """Trading-only balance: positive = customer debit, negative = customer credit."""
        total=0.0
        for x in self.data.get("transactions",[]):
            if str(x.get("customer","")).strip().lower()!=str(customer or "").strip().lower(): continue
            if before and str(x.get("date", ""))[:10] >= before: continue
            total += self.num(x.get("balance", self.num(x.get("sell"))-self.num(x.get("collected",x.get("sell",0)))-self.num(x.get("referral_redemption_value"))))
        # Standalone balance payments settle trading debt/credit without creating a Goods sale.
        for x in self.data.get("customer_payments",[]):
            if str(x.get("customer"," ")).strip().lower()!=str(customer or "").strip().lower(): continue
            if before and str(x.get("date", ""))[:10] >= before: continue
            total -= self.num(x.get("amount"))
        # Account-level non-cash Goods offsets settle trading balance without
        # requiring a link to an individual Goods-sale record.
        for x in self.data.get("customer_goods_offsets",[]):
            if str(x.get("customer"," ")).strip().lower()!=str(customer or "").strip().lower(): continue
            if before and str(x.get("date", ""))[:10] >= before: continue
            total -= self.num(x.get("amount"))
        # Refunds are paid out of existing customer credit, reducing that credit.
        for x in self.data.get("refunds",[]):
            if str(x.get("customer","")).strip().lower()!=str(customer or "").strip().lower(): continue
            if before and str(x.get("date", ""))[:10] >= before: continue
            if str(x.get("status","RECORDED")).upper() not in ("VOID","VOIDED","CANCELLED","REVERSED"):
                total += self.num(x.get("ledger_deduction", x.get("amount")))
        return round(total,2)

    def customer_loan_balance(self, customer, before=""):
        """Loan/debt-only net balance: positive = customer owes business; negative = business owes customer."""
        total=0.0
        for x in self.data.get("obligations",[]):
            party=str(x.get("party") or x.get("name") or x.get("lender") or "").strip()
            if party.lower()!=str(customer or "").strip().lower(): continue
            if before and str(x.get("date", ""))[:10] >= before: continue
            amt=self.num(x.get("outstanding"))+self.num(x.get("interest_outstanding"))
            total += amt if x.get("type")=="Receivable" else -amt
        return round(total,2)

    def balance_label(self, value):
        v=round(self.num(value),2)
        if v>0: return f"DEBIT ₦{v:,.2f}"
        if v<0: return f"CREDIT ₦{abs(v):,.2f}"
        return "₦0.00"

    def customer_contact_record(self, name):
        customers=self.data.setdefault("customers",{})
        rec=customers.get(name,{}) if isinstance(customers,dict) else {}
        return rec if isinstance(rec,dict) else {}

    def customer_phone_numbers(self, name):
        """Return all distinct phone/WhatsApp numbers recorded for a customer."""
        rec = self.customer_contact_record(name)
        values = []
        for key in ("whatsapp", "phone", "phone2", "whatsapp2", "mobile",
                    "mobile2", "additional_phone", "phone_numbers", "whatsapp_numbers"):
            raw = rec.get(key, "")
            candidates = raw if isinstance(raw, (list, tuple, set)) else re.split(r"[,;\n]+", str(raw or ""))
            for item in candidates:
                number = str(item or "").strip()
                if number and number not in values:
                    values.append(number)
        return values

    # V50.72 — timestamp-based customer/referral identity with collision protection.
    def mbal_customer_id(self, name, date_hint=None):
        customers=self.data.setdefault("customers",{})
        existing=customers.get(name,{})
        if isinstance(existing,dict) and existing.get("mbal_id"):
            return str(existing["mbal_id"])
        used={str(v.get("mbal_id","")).upper() for v in customers.values() if isinstance(v,dict)}
        # YYMMDDHHMMSSmmm: milliseconds are included; advance by 1 ms if
        # the same timestamp has already been allocated in this dataset.
        stamp=datetime.now()
        for _ in range(100000):
            candidate="MBAL"+stamp.strftime("%y%m%d%H%M%S")+f"{stamp.microsecond//1000:03d}"
            if candidate not in used:
                return candidate
            stamp += timedelta(milliseconds=1)
        raise RuntimeError("Customer Code allocation exhausted")

    def _build_query_indexes(self):
        """Build safe, transient lookup indexes from the current in-memory data.

        These are deliberately rebuilt from live data rather than persisted, so they
        cannot become stale across edits, restores, imports, or transaction reversals.
        """
        customers=self.data.get("customers",{})
        transactions=self.data.get("transactions",[])
        by_customer={};by_mbal_id={};by_phone={};by_username={};by_platform_id={};ids_by_customer={}
        for name,rec in customers.items():
            if not isinstance(rec,dict):rec={}
            by_customer.setdefault(str(name).casefold(),[]).append(name)
            mid=str(rec.get("mbal_id","") or "").strip().casefold()
            if mid:by_mbal_id.setdefault(mid,[]).append(name)
            username=str(rec.get("whatsapp_username","") or "").strip().casefold().lstrip("@").strip()
            if username:by_username.setdefault(username,[]).append(name)
            for phone in self.customer_phone_numbers(name):
                digits=re.sub(r"\D","",str(phone or ""))
                if digits:by_phone.setdefault(digits,[]).append(name)
        tx_by_customer={};tx_by_platform_id={}
        for pos,tx in enumerate(transactions):
            if not isinstance(tx,dict):continue
            name=str(tx.get("customer","") or "").strip()
            if name:tx_by_customer.setdefault(name,[]).append((pos,tx))
            for a in self.transaction_allocations(tx):
                plat=str(a.get("platform","") or "").strip()
                pid=str(a.get("customer_id","") or "").strip()
                if plat and pid:
                    tx_by_platform_id.setdefault((plat.casefold(),pid.casefold()),[]).append((pos,name,tx))
                    if name and "," not in pid and ";" not in pid:
                        bucket=ids_by_customer.setdefault(name,{})
                        values=bucket.setdefault(plat,[])
                        if pid not in values:values.append(pid)
        # Master IDs are also searchable, including IDs not yet used in a sale.
        for name,rec in customers.items():
            if not isinstance(rec,dict):continue
            for plat,values in (rec.get("platform_ids") or {}).items():
                for pid in self._id_list(values):
                    pid=str(pid or "").strip()
                    if pid and "," not in pid and ";" not in pid:
                        tx_by_platform_id.setdefault((str(plat).strip().casefold(),pid.casefold()),[])
                        bucket=ids_by_customer.setdefault(str(name),{})
                        values=bucket.setdefault(str(plat).strip(),[])
                        if pid not in values:values.append(pid)
        return {"customer":by_customer,"mbal":by_mbal_id,"phone":by_phone,
                "username":by_username,"tx_customer":tx_by_customer,
                "tx_platform_id":tx_by_platform_id,"ids_by_customer":ids_by_customer}

    def find_existing_customer(self, name="", whatsapp="", allocations=None, exclude=""):
        """Exact identifying matches; shared destination IDs require operator confirmation."""
        customers=self.data.setdefault("customers",{})
        nm=str(name or "").strip().casefold()
        wa=re.sub(r"\D","",str(whatsapp or ""))
        incoming={(str(p).upper(),str(pid).strip().casefold()) for p,pid in (allocations or []) if pid}
        results=[]
        for key,rec in customers.items():
            if key==exclude or not isinstance(rec,dict):continue
            reasons=[]
            if nm and (key.casefold()==nm or str(rec.get("mbal_id","")).casefold()==nm):reasons.append("name / Customer Code")
            others={re.sub(r"\D","",v) for v in self.customer_phone_numbers(key)}
            if wa and len(wa)>=7 and any(other and (wa==other or wa[-10:]==other[-10:]) for other in others):reasons.append("WhatsApp / phone")
            ids=self.customer_platform_ids(key)
            if any((str(p).upper(),str(pid).strip().casefold()) in incoming for p,vals in ids.items() for pid in vals):reasons.append("platform ID (may be shared)")
            if reasons:results.append((key,reasons))
        return results

    def resolve_referral_id(self, value, new_customer=""):
        code=str(value or "").strip().upper()
        if not code:return "",None
        hits=[(name,rec) for name,rec in self.data.get("customers",{}).items()
              if isinstance(rec,dict) and str(rec.get("mbal_id","")).upper()==code]
        if len(hits)!=1:return None,"Referral Code not found or ambiguous."
        if hits[0][0].casefold()==str(new_customer).strip().casefold():return None,"Self-referrals are not permitted."
        return hits[0][0],None

    def migrate_customer_ids(self):
        """Idempotent; do not alter transactions, names, balances or existing IDs."""
        customers=self.data.setdefault("customers",{})
        changed=0
        first={}
        for tx in self.data.get("transactions",[]):
            name=str(tx.get("customer") or "").strip();dt=str(tx.get("date") or "")
            if name and dt and (name not in first or dt<first[name]):first[name]=dt
        for name,rec in customers.items():
            if not isinstance(rec,dict):continue
            if not rec.get("mbal_id"):
                rec["mbal_id"]=self.mbal_customer_id(name,rec.get("created_at") or first.get(name))
                if not rec.get("created_at") and not first.get(name):rec["mbal_id_date_source"]="migration_date_unknown"
                changed+=1
        return changed

    def ensure_customer_contact(self, name, whatsapp="", phone=""):
        """Reuse one person/contact profile across trading and loans without merging their balances."""
        name=str(name or "").strip()
        if not name:return {}
        customers=self.data.setdefault("customers",{})
        rec=customers.get(name,{}) if isinstance(customers.get(name,{}),dict) else {}
        rec.setdefault("record_id",uuid.uuid4().hex);rec.setdefault("created_at",datetime.now().strftime("%Y-%m-%d %H:%M:%S"));rec["name"]=name
        if whatsapp and not rec.get("whatsapp"):rec["whatsapp"]=str(whatsapp).strip()
        if phone and not rec.get("phone"):rec["phone"]=str(phone).strip()
        customers[name]=rec
        return rec

    def _receipt_output_path(self, prefix="Transaction_Receipt"):
        fn=f"00_Mr_Brownian_{prefix}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.png"
        return self.report_output_path(fn)[0]

    def _receipt_font(self, size, bold=False):
        """Load a real scalable Android TrueType font; never silently fall back to PIL's tiny bitmap font."""
        from PIL import ImageFont
        candidates = (
            ["/system/fonts/Roboto-Bold.ttf",
             "/system/fonts/RobotoCondensed-Bold.ttf",
             "/system/fonts/NotoSans-Bold.ttf",
             "/system/fonts/DroidSans-Bold.ttf"]
            if bold else
            ["/system/fonts/Roboto-Regular.ttf",
             "/system/fonts/RobotoCondensed-Regular.ttf",
             "/system/fonts/NotoSans-Regular.ttf",
             "/system/fonts/DroidSans.ttf"]
        )
        for fp in candidates:
            try:
                if os.path.isfile(fp):
                    return ImageFont.truetype(fp, int(size))
            except Exception:
                pass
        # Pillow normally ships DejaVuSans on Pydroid3; try by family name.
        for family in (("DejaVuSans-Bold.ttf" if bold else "DejaVuSans.ttf"),
                       ("Arial Bold.ttf" if bold else "Arial.ttf")):
            try:
                return ImageFont.truetype(family, int(size))
            except Exception:
                pass
        raise RuntimeError("No scalable TrueType font was found for receipt rendering.")


    def _receipt_customer_folder(self):
        """Permanent customer-receipt folder in shared internal storage."""
        folder="/storage/emulated/0/Mr Brownian/Customer Receipts"
        os.makedirs(folder, exist_ok=True)
        return folder

    def _receipt_safe_name(self, value):
        value=re.sub(r"[^A-Za-z0-9_-]+","_",str(value or "Customer").strip())
        return value.strip("_") or "Customer"

    def _dated_signature_image(self, max_width=560, max_height=190, date_value=None):
        """Render the saved handwritten signature with the supplied transaction date."""
        from PIL import Image as PILImage, ImageDraw
        import io, base64
        try:
            raw=PILImage.open(io.BytesIO(base64.b64decode(self.TRACED_SIGNATURE_B64))).convert("RGBA")
        except Exception:
            return None
        # Remove the off-white/grey signature-paper rectangle using per-pixel
        # luminance alpha; handwritten dark-brown strokes remain unmodified.
        original_alpha=raw.getchannel("A")
        if original_alpha.getextrema() != (255,255):
            # The supplied brown-ink signature PNG contains faint, nonzero
            # alpha throughout its background (about 23/255). Remove that
            # ghost matte while keeping the full-opacity handwritten strokes.
            mask=original_alpha.point(lambda v:max(0,min(255,int((v-75)*255/180))))
        else:
            # Alternative signature assets may be opaque scans on white paper.
            grey=raw.convert("RGB").convert("L")
            mask=grey.point(lambda v:max(0,min(255,int((235-v)*3))))
        raw.putalpha(mask)
        sig_h=max(95,max_height-52)
        raw.thumbnail((max_width-24,sig_h),PILImage.LANCZOS)
        canvas=PILImage.new("RGBA",(max_width,max_height),(255,255,255,0))
        sx=(max_width-raw.width)//2
        canvas.alpha_composite(raw,(sx,0))
        parsed_date=None
        if date_value:
            raw_date=str(date_value).strip()
            for fmt in ("%Y-%m-%d %H:%M:%S", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%d/%m/%Y", "%d/%m/%y"):
                try:
                    parsed_date=datetime.strptime(raw_date[:19],fmt)
                    break
                except (TypeError,ValueError):
                    continue
        signed_date=parsed_date or datetime.now()
        date_text=signed_date.strftime("%d/%m/%y")
        d=ImageDraw.Draw(canvas)
        f=self._receipt_font(30,False)
        bb=d.textbbox((0,0),date_text,font=f)
        dx=(max_width-(bb[2]-bb[0]))//2
        dy=min(max_height-(bb[3]-bb[1])-4,raw.height+5)
        d.text((dx,dy),date_text,font=f,fill=(78,43,34,255))
        return canvas

    def _receipt_transaction_ledger_balances(self, tx):
        """Reconstruct sale receipt balances from ledger movements, never snapshots.

        Transaction ``balance`` fields are historical snapshots and may be stale
        or inconsistent with the actual payment. For each sale, derive its ledger
        movement from sale value less cash collected and referral redemption value.
        Positive means customer debit; negative means customer credit.
        """
        name = str(tx.get("customer") or "").strip().casefold()
        target_date = str(tx.get("date") or "")
        target_id = str(tx.get("record_id") or "")
        transactions = self.data.get("transactions", [])
        target_index = next((i for i, item in enumerate(transactions)
                             if ((target_id and str(item.get("record_id") or "") == target_id)
                                 or item is tx)), None)

        def sale_movement(item):
            sell = self.num(item.get("sell"))
            collected = self.num(item.get("collected", item.get("sell", 0)))
            redeemed_value = self.num(item.get("referral_redemption_value"))
            return round(sell - collected - redeemed_value, 2)

        opening = 0.0
        for i, item in enumerate(transactions):
            if str(item.get("customer") or "").strip().casefold() != name:
                continue
            stamp = str(item.get("date") or "")
            is_target = ((item is tx) or
                         (target_id and str(item.get("record_id") or "") == target_id))
            if is_target:
                continue
            before_target = (stamp < target_date or
                             (stamp == target_date and target_index is not None and i < target_index))
            if before_target:
                # Do not read item['balance']: it is only a cached snapshot.
                opening += sale_movement(item)

        # Standalone settlements and account-level offsets reduce the balance.
        for collection in ("customer_payments", "customer_goods_offsets"):
            for item in self.data.get(collection, []):
                if (str(item.get("customer") or "").strip().casefold() == name
                        and str(item.get("date") or "") < target_date):
                    opening -= self.num(item.get("amount"))

        # Recorded refunds consume customer credit and therefore increase the net
        # trading balance. Ignore voided/reversed refund records.
        for item in self.data.get("refunds", []):
            if (str(item.get("customer") or "").strip().casefold() == name
                    and str(item.get("date") or "") < target_date
                    and str(item.get("status", "RECORDED")).upper() not in
                    ("VOID", "VOIDED", "CANCELLED", "REVERSED")):
                opening += self.num(item.get("ledger_deduction", item.get("amount")))

        opening = round(opening, 2)
        # Crucial: ignore tx['balance']; derive this sale's actual movement.
        closing = round(opening + sale_movement(tx), 2)
        return opening, closing

    def create_receipt_image(self, rec, payment=False):
        """V40.17 fixed-artwork receipt: permanent branded artwork + dynamic transaction overlay."""
        try:
            from PIL import Image as PILImage, ImageDraw
        except Exception:
            self.popup("Receipt Image","Pillow is required for graphical receipts in Pydroid3.")
            return ""

        _pa=[] if payment else self.transaction_allocations(rec)
        _preview_alloc=_pa
        if not payment and not _pa:
            _pa=[{"platform":rec.get("platform",""),"customer_id":self.transaction_id_text(rec,True),"qty":rec.get("qty",0)}]
        if not payment:
            _pv,_cv=self._receipt_transaction_ledger_balances(rec)
        else:
            _pv=self.num(rec.get("previous_trading_balance",0))
            _cv=self.num(rec.get("trading_balance_after",_pv-self.num(rec.get("amount"))))
        _previous_preview=_pv
        _current_preview=_cv
        _extra=max(0,len(_pa)-1)*78
        # Add only the balance rows that are actually displayed. Outstanding
        # balance remains visible at zero when a non-zero previous balance exists.
        if not payment:
            _extra += (76 if abs(_pv)>0.004 else 0)
            _extra += (80 if abs(_cv)>0.004 or abs(_pv)>0.004 else 0)
            _extra += 58  # account-status message remains on every sale receipt
        else:
            _extra += (76 if abs(_pv)>0.004 else 0)
            _extra += (80 if abs(_cv)>0.004 or abs(_pv)>0.004 else 0)
            _extra += (58 if abs(_cv)>0.004 or abs(_pv)>0.004 else 0)
        _extra += (76 if (not payment and self.num(rec.get("advance_credit_applied")) > 0.004) else 0)
        # Reserve sufficient footer space for long receipts so the thank-you
        # lines can never be forced upward over the account-status message.
        W,H=1080,1726+_extra
        white=(255,255,255); ink=(7,18,66); navy=(8,36,126)
        blue=(0,83,185); deepblue=(0,42,112); gold=(229,166,22)
        red=(218,0,13); pale=(226,242,253); cream=(255,244,197)
        mint=(231,246,230); pink=(255,220,226); green=(0,116,57)

        im=PILImage.new("RGB",(W,H),white)
        d=ImageDraw.Draw(im)

        # ---- FIXED ARTWORK LAYER ----
        # Blue/gold sweeping top and bottom frame, intentionally drawn independently of transaction data.
        d.polygon([(0,0),(1080,0),(1080,92),(930,72),(760,110),(575,82),(380,105),(190,78),(0,155)],fill=deepblue)
        d.polygon([(0,42),(220,15),(410,48),(610,32),(790,64),(960,25),(1080,35),(1080,52),
                   (960,42),(790,82),(610,49),(410,66),(220,33),(0,62)],fill=gold)
        bt=H-170
        d.polygon([(0,bt),(160,H-105),(355,H-70),(560,H-45),(760,H-75),(925,H-120),(1080,H-180),(1080,H),(0,H)],fill=blue)
        d.line([(0,bt),(165,H-112),(360,H-82),(560,H-60),(760,H-90),(925,H-132),(1080,H-192)],fill=gold,width=12)
        d.line([(0,bt+30),(165,H-86),(360,H-55),(560,H-30),(760,H-60),(925,H-100),(1080,H-158)],fill=deepblue,width=18)

        # Company logo: restore the original receipt rendering that was used before
        # the attempted inset/contain adjustment. The embedded artwork is already
        # square, so fit preserves its proportions and the original circular mask.
        try:
            from PIL import ImageOps
            lp=self._asset_file("mr_brownian_company_logo_v40.jpg",self.COMPANY_LOGO_B64)
            logo=PILImage.open(lp).convert("RGB")
            logo=ImageOps.fit(logo,(160,160),method=PILImage.Resampling.LANCZOS)
            mask=PILImage.new("L",(160,160),0)
            ImageDraw.Draw(mask).ellipse((1,1,158,158),fill=255)
            lx,ly=64,159
            im.paste(logo,(lx,ly),mask)
            d.ellipse((lx-4,ly-4,lx+163,ly+163),outline=gold,width=8)
        except Exception:
            d.ellipse((64,159,224,319),fill=(5,5,5),outline=gold,width=8)
            d.text((82,192),"MB",font=self._receipt_font(64,True),fill=gold)

        fcompany=self._receipt_font(64,True)
        fphone=self._receipt_font(55,True)
        ftitle=self._receipt_font(62,True)
        flabel=self._receipt_font(42,True)
        fvalue=self._receipt_font(44,True)
        fsmall=self._receipt_font(36,True)
        fthanks=self._receipt_font(43,True)
        fsig=self._receipt_font(48,True)

        # Company heading is fixed artwork.
        company="MR BROWNIAN AGENCIES LTD"
        x0=278; maxw=770
        fs=64
        fcompany=self._receipt_font(fs,True)
        while d.textbbox((0,0),company,font=fcompany)[2] > maxw and fs>44:
            fs-=2; fcompany=self._receipt_font(fs,True)
        d.text((x0,160),company,font=fcompany,fill=navy)

        # Fixed company WhatsApp bar.
        d.rounded_rectangle((320,238,1015,312),35,fill=navy)
        phone="+2349039854892"
        bb=d.textbbox((0,0),phone,font=fphone)
        d.text(((320+1015-(bb[2]-bb[0]))/2,247),phone,font=fphone,fill=white)

        # Fixed receipt title.
        title="PAYMENT RECEIPT" if payment else "TRANSACTION RECEIPT"
        d.rounded_rectangle((36,335,1044,435),46,fill=red,outline=gold,width=7)
        bb=d.textbbox((0,0),title,font=ftitle)
        d.text(((W-(bb[2]-bb[0]))/2,352),title,font=ftitle,fill=white)

        # ---- DYNAMIC TRANSACTION OVERLAY ----
        name=str(rec.get("customer") or "Unspecified")
        contact=self.customer_contact_record(name)
        wa=self.normalize_whatsapp_number(rec.get("whatsapp") or contact.get("whatsapp") or contact.get("phone") or "")
        dt=str(rec.get("date") or "")
        date=dt[:10] or datetime.now().strftime("%Y-%m-%d")
        raw=dt[11:19]
        try: tm=datetime.strptime(raw,"%H:%M:%S").strftime("%I:%M %p").lstrip("0")
        except Exception: tm=raw or datetime.now().strftime("%I:%M %p").lstrip("0")

        info=[("DATE",date),("TIME",tm),("CUSTOMER",name),
              ("CUSTOMER CODE",self.mbal_id_for_customer(name,rec) or "Not assigned"),
              ("WHATSAPP NO.",f"+{wa}" if wa else "Not recorded")]

        left,right=34,1046
        label_x=74
        y=450; rh=76

        def fit_font(text, size=40, max_width=490, bold=True, minimum=30):
            f=self._receipt_font(size,bold)
            while d.textbbox((0,0),str(text),font=f)[2] > max_width and size>minimum:
                size-=2; f=self._receipt_font(size,bold)
            return f

        # V40.22: calculate one value column from the widest label actually present.
        # The gap is exactly the rendered width of two spaces; graphical receipts use pixels.
        _labels=[k for k,_ in info]
        if not payment:
            for a in _preview_alloc:
                _labels.append(f"{str(a.get('platform') or rec.get('platform','')).upper()} ID")
            # Measure actual summary labels, including PURCHASED QUANTITY and optional REFERRAL BONUS.
            _labels.append("PURCHASED QUANTITY")
            _preview_vested_qty = sum(self.num(r.get("qty")) for r in rec.get("referral_reward_redemptions", []))
            if _preview_vested_qty > 0:
                _labels.append("REFERRAL BONUS")
            _labels += ["AMOUNT","AMOUNT PAID"]
        else:
            _labels += ["PAYMENT RECEIVED"]
            if rec.get("method"): _labels.append("PAYMENT METHOD")
            if rec.get("reference"): _labels.append("REFERENCE")
        if not payment and self.num(rec.get("advance_credit_applied")) > 0.004:
            _labels.append("ADVANCE CREDIT APPLIED")
        if not payment:
            if abs(_previous_preview)>0.004:
                _labels.append("PREVIOUS BALANCE")
            if abs(_current_preview)>0.004 or abs(_previous_preview)>0.004:
                _labels.append("OUTSTANDING BALANCE")
        else:
            if abs(previous if 'previous' in locals() else _previous_preview)>0.004:
                _labels.append("PREVIOUS BALANCE")
            if abs(current if 'current' in locals() else _current_preview)>0.004 or abs(previous if 'previous' in locals() else _previous_preview)>0.004:
                _labels.append("OUTSTANDING BALANCE")
        _widest=max(d.textbbox((0,0),lab,font=flabel)[2] for lab in _labels)
        _two_spaces=d.textbbox((0,0),"  ",font=flabel)[2]
        value_x=label_x+_widest+_two_spaces

        def row(label,value,fill,value_color=ink, value_bold=True, height=rh):
            nonlocal y
            d.rounded_rectangle((left,y,right,y+height-7),14,fill=fill)
            d.text((label_x,y+13),label,font=flabel,fill=ink)
            vf=fit_font(value,44,max(160,right-value_x-24),value_bold)
            d.text((value_x,y+11),str(value),font=vf,fill=value_color)
            y+=height

        for k,v in info:
            row(k,v,pale,navy if k=="CUSTOMER" else ink,True)

        allocations=[]
        if not payment:
            allocations=self.transaction_allocations(rec)
            if not allocations:
                allocations=[{"platform":rec.get("platform",""),
                              "customer_id":self.transaction_id_text(rec,True),
                              "qty":rec.get("qty",0)}]
            for a in allocations:
                platform=str(a.get("platform") or rec.get("platform","")).upper()
                cid=str(a.get("customer_id") or "")
                qty=self.num(a.get("qty"))
                row(f"{platform} ID",f"{cid} ({qty:,.0f})",cream,navy,True,78)

            credit_quantities = rec.get("platform_credit_quantities", {})
            if isinstance(credit_quantities, dict) and credit_quantities:
                total_credit_qty = sum(self.num(v) for v in credit_quantities.values())
                vested_qty = sum(self.num(r.get("qty")) for r in rec.get("referral_reward_redemptions", []))
                summary=[("PURCHASED QUANTITY",f"{self.num(rec.get('qty')):,.0f}")]
                if vested_qty > 0:
                    summary.append(("REFERRAL BONUS",f"{vested_qty:,.0f}"))
            else:
                summary=[("PURCHASED QUANTITY",f"{self.num(rec.get('qty')):,.0f}")]
            summary += [("AMOUNT",f"₦{self.num(rec.get('sell')):,.2f}"),
                        ("AMOUNT PAID",f"₦{self.num(rec.get('collected',rec.get('sell',0))):,.2f}")]
            if self.num(rec.get("advance_credit_applied")) > 0.004:
                summary.append(("ADVANCE CREDIT APPLIED", f"₦{self.num(rec.get('advance_credit_applied')):,.2f}"))
            # Referral redemptions are coin quantities, not a Naira customer
            # balance. The actual coin contribution is already shown above.
            previous,current=self._receipt_transaction_ledger_balances(rec)
        else:
            summary=[("PAYMENT RECEIVED",f"₦{self.num(rec.get('amount')):,.2f}")]
            if rec.get("method"): summary.append(("PAYMENT METHOD",str(rec.get("method"))))
            if rec.get("reference"): summary.append(("REFERENCE",str(rec.get("reference"))))
            previous=self.num(rec.get("previous_trading_balance"))
            current=self.num(rec.get("trading_balance_after"))

        for k,v in summary:
            row(k,v,mint,ink,True)

        if not payment:
            if abs(previous)>0.004:
                row("PREVIOUS BALANCE",self.balance_label(previous),cream,ink,True)
            if abs(current)>0.004 or abs(previous)>0.004:
                value=self.balance_label(current) if abs(current)>0.004 else "₦0.00"
                row("OUTSTANDING BALANCE",value,pink,green if current<=0 else red,True,80)
            if current < -0.004:
                msg=f"You have a credit balance of ₦{abs(current):,.2f} with us. Kindly deduct it from your next payment."
            elif current > 0.004:
                msg="Please take care of the outstanding balance in your next payment."
            else:
                msg="Your account is fully settled."
            mh=58
            d.rounded_rectangle((left,y,right,y+mh-6),14,fill=mint)
            mf=fit_font(msg,31, right-left-70,True,24)
            bb=d.textbbox((0,0),msg,font=mf)
            d.text(((W-(bb[2]-bb[0]))/2,y+13),msg,font=mf,fill=green if current<=0 else red)
            y+=mh
        elif abs(previous)>0.004 or abs(current)>0.004:
            if abs(previous)>0.004:
                row("PREVIOUS BALANCE",self.balance_label(previous),cream,ink,True)
            if abs(current)>0.004 or abs(previous)>0.004:
                value=self.balance_label(current) if abs(current)>0.004 else "₦0.00"
                row("OUTSTANDING BALANCE",value,pink,green if current<=0 else red,True,80)
            msg=(f"You have a credit balance of ₦{abs(current):,.2f} with us. Kindly deduct it from your next payment." if current < -0.004 else ("Please take care of the outstanding balance in your next payment." if current > 0.004 else "Your account is fully settled."))
            mh=58; d.rounded_rectangle((left,y,right,y+mh-6),14,fill=mint)
            mf=fit_font(msg,31,right-left-70,True,24); bb=d.textbbox((0,0),msg,font=mf)
            d.text(((W-(bb[2]-bb[0]))/2,y+13),msg,font=mf,fill=green if current<=0 else red); y+=mh

        # Shared Payment and Transaction image-receipt footer spacing.
        # Keep the thank-you text clearly separated from the account-status panel.
        thanks_y=max(y+72,H-455)
        thanks1="Thank you so much for the patronage."
        thanks2="You are awesome."
        for i,msg in enumerate((thanks1,thanks2)):
            bb=d.textbbox((0,0),msg,font=fthanks)
            d.text(((W-(bb[2]-bb[0]))/2,thanks_y+i*52),msg,font=fthanks,fill=navy)

        signed=self._dated_signature_image(560,190)
        if signed is not None:
            # Center signature/date on the complete existing M/B + Mr Brownian closing.
            closing_center=W//2
            im.paste(signed,(int(closing_center-signed.width/2),thanks_y+92),signed)

        # Existing graphical M/B closing remains directly below the signature.
        sy=thanks_y+300
        d.ellipse((340,sy,410,sy+70),fill=(25,92,220))
        mb=self._receipt_font(49,True)
        bb=d.textbbox((0,0),"M",font=mb); d.text((375-(bb[2]-bb[0])/2,sy+5),"M",font=mb,fill=white)
        d.rounded_rectangle((422,sy,492,sy+70),15,fill=(235,45,78))
        bb=d.textbbox((0,0),"B",font=mb); d.text((457-(bb[2]-bb[0])/2,sy+5),"B",font=mb,fill=white)
        d.text((515,sy+10),"Mr Brownian",font=fsig,fill=navy)

        folder=self._receipt_customer_folder()
        stamp=datetime.now().strftime("%Y%m%d_%H%M%S")
        kind="Payment" if payment else "Transaction"
        filename=f"Mr_Brownian_{kind}_Receipt_{self._receipt_safe_name(name)}_{stamp}.jpg"
        path=os.path.join(folder,filename)
        if not payment:
            # Automatically mark every transaction JPG as SUPPLIED, without
            # changing the underlying transaction fields or receipt design.
            from PIL import Image as PILImage, ImageDraw
            overlay=PILImage.new("RGBA",im.size,(0,0,0,0))
            text="SUPPLIED"
            wf=self._receipt_font(174,True)
            tb=ImageDraw.Draw(overlay).textbbox((0,0),text,font=wf)
            layer=PILImage.new("RGBA",(tb[2]-tb[0]+55,tb[3]-tb[1]+55),(0,0,0,0))
            ImageDraw.Draw(layer).text((25-tb[0],25-tb[1]),text,font=wf,fill=(28,82,138,53))
            layer=layer.rotate(27,expand=True,resample=getattr(getattr(PILImage,"Resampling",PILImage),"BICUBIC"))
            overlay.alpha_composite(layer,((W-layer.width)//2,(H-layer.height)//2))
            im=PILImage.alpha_composite(im.convert("RGBA"),overlay).convert("RGB")
        im.save(path,"JPEG",quality=95,optimize=True,subsampling=0)
        return path

    def _scan_receipt_into_gallery(self, path):
        """Ask Android MediaScanner to index the saved receipt without moving it."""
        try:
            from jnius import autoclass, PythonJavaClass, java_method
            PythonActivity=autoclass("org.kivy.android.PythonActivity")
            MediaScannerConnection=autoclass("android.media.MediaScannerConnection")
            String=autoclass("java.lang.String")
            # Static scanFile accepts String[] paths/mimeTypes; Pyjnius converts Python lists.
            MediaScannerConnection.scanFile(
                PythonActivity.mActivity,
                [str(path)],
                ["image/jpeg"],
                None
            )
            return True
        except Exception:
            # Legacy broadcast fallback.
            try:
                from jnius import autoclass
                Intent=autoclass("android.content.Intent")
                Uri=autoclass("android.net.Uri")
                File=autoclass("java.io.File")
                PythonActivity=autoclass("org.kivy.android.PythonActivity")
                intent=Intent(Intent.ACTION_MEDIA_SCANNER_SCAN_FILE)
                intent.setData(Uri.fromFile(File(str(path))))
                PythonActivity.mActivity.sendBroadcast(intent)
                return True
            except Exception:
                return False

    def share_receipt_image(self, rec, payment=False):
        """Save the receipt image, then let the user choose image-only or image + text."""
        path=self.create_receipt_image(rec,payment)
        if not path or not os.path.isfile(path):
            self.popup("Receipt Error","The receipt image could not be created.")
            return
        self._scan_receipt_into_gallery(path)
        from kivy.uix.popup import Popup
        from kivy.uix.boxlayout import BoxLayout
        from kivy.uix.label import Label
        from kivy.uix.button import Button
        box=BoxLayout(orientation="vertical",padding=dp(14),spacing=dp(10))
        box.add_widget(Label(text="How would you like to share the receipt?",color=self.TEXT,
                             halign="center",valign="middle",size_hint_y=None,height=dp(56)))
        pop=Popup(title="SHARE RECEIPT",content=box,size_hint=(.9,None),height=dp(250),
                  auto_dismiss=True,background_color=self.PANEL)
        def share(include_text):
            pop.dismiss()
            name=str(rec.get("customer") or "").strip()
            contact=self.customer_contact_record(name)
            digits=self.normalize_whatsapp_number(rec.get("whatsapp") or contact.get("whatsapp") or contact.get("phone") or "")
            if not digits:
                return self.popup("WhatsApp","Receipt saved in Customer Receipts, but no valid WhatsApp number is available.\n\n"+path)
            try:
                from urllib.parse import quote
                from jnius import autoclass
                Intent=autoclass("android.content.Intent")
                Uri=autoclass("android.net.Uri")
                PythonActivity=autoclass("org.kivy.android.PythonActivity")
                url="https://wa.me/"+digits
                if include_text:
                    msg=self.payment_receipt_text(rec) if payment else self.receipt_image_promotion_text(rec)
                    url += "?text="+quote(msg,safe="")
                intent=Intent(Intent.ACTION_VIEW,Uri.parse(url))
                intent.setPackage("com.whatsapp.w4b")
                PythonActivity.mActivity.startActivity(intent)
            except Exception as e:
                mode="with text" if include_text else "image-only"
                self.popup("Receipt Saved",f"Receipt saved in Internal storage > Mr Brownian > Customer Receipts.\n\nCould not open WhatsApp Business ({mode}): {e}")
        for label,with_text in (("IMAGE + TEXT",True),("IMAGE ONLY",False),("CANCEL",None)):
            btn=Button(text=label,size_hint_y=None,height=dp(48),font_size="16sp",bold=True)
            if with_text is True: btn.background_color=self.SUCCESS
            elif with_text is False: btn.background_color=self.PRIMARY
            else: btn.background_color=self.MUTED
            btn.bind(on_release=(lambda _,v=with_text: pop.dismiss() if v is None else share(v)))
            box.add_widget(btn)
        pop.open()

    def transaction_receipt_text(self, tx):
        """V40.19 exact alignment, calculated header centering and centered wrapped footer."""
        import textwrap
        name=str(tx.get("customer") or "Unspecified")
        rec=self.customer_contact_record(name)
        wa=self.normalize_whatsapp_number(tx.get("whatsapp") or rec.get("whatsapp") or rec.get("phone") or "")
        dt=str(tx.get("date") or "")
        date=dt[:10] or datetime.now().strftime("%Y-%m-%d")
        rawtime=dt[11:19]
        try: tm=datetime.strptime(rawtime,"%H:%M:%S").strftime("%I:%M %p").lstrip("0")
        except Exception: tm=rawtime or "Time not recorded"
        previous,current=self._receipt_transaction_ledger_balances(tx)
        rows=[("DATE",date),("TIME",tm),("CUSTOMER",name),("CUSTOMER CODE",self.mbal_id_for_customer(name,tx) or "Not assigned"),("WHATSAPP NO.",f"+{wa}" if wa else "Not recorded")]
        alloc=self.transaction_allocations(tx)
        if alloc:
            for a in alloc:
                rows.append((f"{str(a.get('platform') or tx.get('platform','')).upper()} ID",f"{a.get('customer_id','')} ({self.num(a.get('qty')):,.0f})"))
        else:
            rows.append((f"{str(tx.get('platform','')).upper()} ID",f"{self.transaction_id_text(tx,True)} ({self.num(tx.get('qty')):,.0f})"))
        rows += [("PURCHASED QUANTITY",f"{self.num(tx.get('qty')):,.0f}")]
        credit_quantities = tx.get("platform_credit_quantities", {})
        if isinstance(credit_quantities, dict) and credit_quantities:
            total_credit_qty = sum(self.num(v) for v in credit_quantities.values())
            vested_qty = sum(self.num(r.get("qty")) for r in tx.get("referral_reward_redemptions", []))
            if vested_qty > 0:
                rows.append(("REFERRAL BONUS", f"{vested_qty:,.0f}"))
        rows += [("AMOUNT",f"₦{self.num(tx.get('sell')):,.2f}"),("AMOUNT PAID",f"₦{self.num(tx.get('collected',tx.get('sell',0))):,.2f}")]
        if self.num(tx.get("advance_credit_applied")) > 0.004:
            rows.append(("ADVANCE CREDIT APPLIED", f"₦{self.num(tx.get('advance_credit_applied')):,.2f}"))
        # Referral bonus is a coin quantity shown above, never a Naira balance.
        br=[]
        if abs(previous)>0.004:
            br.append(("PREVIOUS BALANCE",self.balance_label(previous)))
        if abs(current)>0.004 or abs(previous)>0.004:
            br.append(("OUTSTANDING BALANCE",self.balance_label(current) if abs(current)>0.004 else "₦0.00"))
        allrows=rows+br
        tw=max(len(k) for k,v in allrows)
        main=[f"{k.ljust(tw)}  {v}" for k,v in rows]
        bals=[f"{k.ljust(tw)}  {v}" for k,v in br]
        rw=max(len(x) for x in main+bals)
        def ctr(s,w): return " "*max(0,(w-len(s))//2)+s
        company="MR BROWNIAN AGENCIES LTD"; cw=len(company)
        L=[ctr(company,cw),ctr("+2349039854892",cw),"",ctr("TRANSACTION RECEIPT",cw),""]+main
        if bals:L += [""]+bals
        if bals:
            if current>0.004:L += ["","Please take care of the outstanding balance in your next payment."]
            elif current< -0.004:L += ["",f"You have a credit balance of ₦{abs(current):,.2f} with us. Kindly deduct it from your next payment."]
            else:L += ["","Your account is fully settled."]
        thanks="Thank you so much for the patronage. You are awesome."
        lines=textwrap.wrap(thanks,width=max(12,rw),break_long_words=False,break_on_hyphens=False) or [thanks]
        L += [""]+[ctr(x,rw) for x in lines]
        L += ["",ctr("Ⓜ️🅱️ Mr Brownian",rw)]
        # WhatsApp monospace covers the entire receipt. No bold/italic markers inside.
        L=[line.replace(chr(96)*3, chr(39)*3) for line in L]
        L=["```"]+L+["```"]
        return "\n".join(L)

    def _open_customer_whatsapp_prefill(self, rec, text):
        """Open the exact customer's WhatsApp Business chat with supplied text prefilled."""
        name=str(rec.get("customer") or "").strip()
        contact=self.customer_contact_record(name)
        digits=self.normalize_whatsapp_number(rec.get("whatsapp") or contact.get("whatsapp") or contact.get("phone") or "")
        if not digits:
            self.popup("WhatsApp","No valid WhatsApp number is available for this customer.")
            return False
        try:
            from urllib.parse import quote
            from jnius import autoclass
            Intent=autoclass("android.content.Intent")
            Uri=autoclass("android.net.Uri")
            PythonActivity=autoclass("org.kivy.android.PythonActivity")
            url="https://wa.me/"+digits+"?text="+quote(str(text),safe="")
            intent=Intent(Intent.ACTION_VIEW,Uri.parse(url))
            intent.setPackage("com.whatsapp.w4b")
            PythonActivity.mActivity.startActivity(intent)
            return True
        except Exception as e:
            self.popup("WhatsApp",f"Could not open WhatsApp Business: {e}")
            return False

    def send_transaction_receipt_text(self, tx):
        """RECEIPT TEXT: open customer's WhatsApp Business chat with the text receipt."""
        return self._open_customer_whatsapp_prefill(tx,self.transaction_receipt_text(tx))

