    def outgoing_payment_charges(self, payment_amount, intrabank=False):
        """Nigeria outgoing-payment rule agreed for Mr Brownian: N20 bank charge + N1.50 VAT; add N50 stamp duty for payments >= N10,000."""
        a=max(0.0,self.num(payment_amount))
        bank=20.0 if a>0 and not intrabank else 0.0
        vat=1.50 if a>0 and not intrabank else 0.0
        stamp=50.0 if a>=10000.0 else 0.0
        return {"bank_charge":bank,"vat":vat,"stamp_duty":stamp,"total":bank+vat+stamp}

    def record_outgoing_payment_charges(self, payment_amount, description="Outgoing Payment", platform="", ref_id="", capitalize_inventory=False, intrabank=False):
        """Record charge components separately for cash/reporting. Inventory purchases capitalize these charges into the lot cost, so profit must not deduct them a second time."""
        ch=self.outgoing_payment_charges(payment_amount,intrabank=intrabank)
        if ch["total"]<=0:return ch
        now=datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        for category,key in (("Bank Charge","bank_charge"),("VAT on Bank Charge","vat"),("Stamp Duty","stamp_duty")):
            amt=ch[key]
            if amt<=0:continue
            self.data.setdefault("finance",[]).append({"date":now,"kind":"expense","amount":amt,"category":category,"note":description,"platform":platform,"payment_method":"Bank","record_id":self.record_id(),"ref_id":ref_id,"bank_charge_component":key,"intrabank":bool(intrabank),"capitalized_inventory":bool(capitalize_inventory),"non_profit":bool(capitalize_inventory)})
        return ch

    def add_finance(self, kind, amount, category, note="", platform=""):
        self.data.setdefault("finance",[]).append({
            "date":datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            "kind":kind,"amount":float(amount),"category":category,
            "note":note,"platform":platform
        })

    def cash_balance(self):
        bal=float(self.data["global"].get("opening_balance",0))
        for x in self.data.get("finance",[]):
            # Legacy payment-method records remain supported as inventory movements, never cash.
            if str(x.get("payment_method","")).lower()=="Goods":
                continue
            a=float(x.get("amount",0))
            bal += a if x.get("kind")=="income" else -a
        return bal

    def _audit_classification(self):
        """Return broken linked records and standalone/manual finance records separately."""
        txids={str(x.get("record_id")) for x in self.data.get("transactions",[]) if isinstance(x,dict) and x.get("record_id")}
        purchaseids={str(x.get("record_id")) for x in self.data.get("purchases",[]) if isinstance(x,dict) and x.get("record_id")}
        broken=[]; manual=[]
        for f in self.data.get("finance",[]):
            if not isinstance(f,dict):
                broken.append((f,"Malformed finance record")); continue
            cat=str(f.get("category","")); ref=str(f.get("ref_id") or "")
            if cat=="Customer Payment" and ref and ref not in txids:
                broken.append((f,"Customer Payment refers to a missing sale"))
            elif cat in ("Goods Purchase","Withdrawal Acquisition") and ref and ref not in purchaseids:
                broken.append((f,"Acquisition ledger entry refers to a missing acquisition"))
            elif not ref:
                manual.append(f)
        return broken,manual

    def _delete_broken_orphans(self, *_):
        broken,_=self._audit_classification()
        if not broken:
            self.popup("No Broken Orphans","No broken linked finance records were found. Nothing was deleted."); return
        ids={id(x) for x,_ in broken if isinstance(x,dict)}
        self.data["finance"]=[x for x in self.data.get("finance",[]) if id(x) not in ids]
        self.audit("cleanup","finance",self.record_id(),f"Removed {len(ids)} broken linked orphan(s)")
        self.save()
        self.popup("Cleanup Complete",f"Removed {len(ids)} broken linked orphan record(s). Standalone/manual records were preserved.")
        self.refresh_current(self.data_audit)

    def _delete_manual_finance_final(self, rid):
        rec=next((x for x in self.data.get("finance",[]) if isinstance(x,dict) and x.get("record_id")==rid and not x.get("ref_id")),None)
        if not rec:
            self.popup("Not Deleted","The record was not found or is linked to a source record."); return
        self.data["finance"]=[x for x in self.data.get("finance",[]) if x is not rec]
        self.audit("delete","manual_finance",rid,"Deleted explicitly from Data Audit review")
        self.save(); self.popup("Deleted","The selected standalone/manual finance record was deleted.")
        self.refresh_current(self.data_audit)

    def _delete_manual_finance(self, rid):
        self.ask("Confirm Deletion 1 of 2","Are you sure you want to delete this manual finance record?",lambda:self.ask("FINAL CONFIRMATION 2 of 2","This changes the cash balance and financial history. This action cannot be undone. Delete permanently?",lambda:self._delete_manual_finance_final(rid)))

