    def periodic_customer_statement_text(self, name, start, end, summary_only=False, statement_type="Trading"):
        """Customer-safe dated statement; separate payment ledger avoids stale sale outstanding."""
        if not start or not end or start > end:
            raise ValueError("Select a valid start and end date")
        transactions=sorted((x for x in self.data.get("transactions", [])
                             if x.get("customer")==name and self._date_ok(str(x.get("date","")),start,end)),
                            key=lambda x:str(x.get("date","")))
        payments=sorted((x for x in self.data.get("customer_payments", [])
                         if x.get("customer")==name and self._date_ok(str(x.get("date","")),start,end)),
                        key=lambda x:str(x.get("date","")))
        refunds=sorted((x for x in self.data.get("refunds", [])
                        if x.get("customer")==name and self._date_ok(str(x.get("date","")),start,end)
                        and str(x.get("status","RECORDED")).upper() not in ("VOID","VOIDED","CANCELLED","REVERSED")),
                       key=lambda x:str(x.get("date","")))
        prev=(datetime.strptime(start,"%Y-%m-%d")-timedelta(days=1)).strftime("%Y-%m-%d")
        opening=self.customer_trading_balance_asof(name,prev)
        sales=sum(self.num(x.get("sell")) for x in transactions)
        paid_at_sale=sum(self.num(x.get("collected",x.get("sell",0))) for x in transactions)
        redemptions=sum(self.num(x.get("referral_redemption_value")) for x in transactions)
        later_payments=sum(self.num(x.get("amount")) for x in payments)
        refund_total=sum(self.num(x.get("ledger_deduction", x.get("amount"))) for x in refunds)
        closing=self.customer_trading_balance_asof(name,end)
        expected=round(opening+sales-paid_at_sale-redemptions-later_payments+refund_total,2)
        if abs(expected-closing)>.02:
            raise ValueError("Trading ledger does not reconcile for "+name)
        lines=["*MR BROWNIAN AGENCIES LTD*","*CUSTOMER ACCOUNT STATEMENT*",
               "*CUSTOMER:* "+name,"*PERIOD:* "+start+" to "+end,""]
        if statement_type in ("Trading","Combined"):
            lines.extend(["*TRADING ACCOUNT*",f"PREVIOUS BALANCE: {self.balance_label(opening)}"])
            if not summary_only:
                for x in transactions:
                    line = (f"{str(x.get('date',''))[:16]} | {x.get('platform','')} | {self.num(x.get('qty')):,.0f} Goods | "
                            f"Sale ₦{self.num(x.get('sell')):,.2f} | Cash ₦{self.num(x.get('collected',x.get('sell',0))):,.2f}")
                    if self.num(x.get("referral_redemption_value")) > 0.004:
                        line += f" | Vested coins used ₦{self.num(x.get('referral_redemption_value')):,.2f}"
                    lines.append(line)
                for x in payments:
                    lines.append(f"{str(x.get('date',''))[:16]} | BALANCE PAYMENT ({x.get('method','')}) | ₦{self.num(x.get('amount')):,.2f}")
                for x in refunds:
                    lines.append(f"{str(x.get('date',''))[:16]} | REFUND ({x.get('method','')}) | Refund ₦{self.num(x.get('amount')):,.2f} | Charges ₦{self.num(x.get('total_charges')):,.2f} | Credit deducted ₦{self.num(x.get('ledger_deduction', x.get('amount'))):,.2f} | {x.get('reason','')}")
            lines.extend([f"TOTAL SALES: ₦{sales:,.2f}",f"CASH PAID AT SALE: ₦{paid_at_sale:,.2f}",
                          f"VESTED REFERRAL COINS REDEEMED: ₦{redemptions:,.2f}",
                          f"SUBSEQUENT BALANCE PAYMENTS: ₦{later_payments:,.2f}",
                          f"REFUNDS + TRANSFER CHARGES DEDUCTED FROM CREDIT: ₦{refund_total:,.2f}",
                          f"*OUTSTANDING BALANCE: {self.balance_label(closing)}*",""])
            if closing>.004:lines.append("Kindly settle your outstanding trading balance.")
            elif closing<-.004:lines.append("Your trading account has a credit balance.")
        if statement_type in ("Loans & Debts","Combined"):
            # The loan balance helper is current-state only. Never mislabel it as historical.
            if end != datetime.now().strftime("%Y-%m-%d"):
                raise ValueError("Historical loan balance is not supported; use Trading or an end date of today")
            loan=self.customer_loan_balance(name)
            lines.extend(["*LOANS & DEBTS*",f"CURRENT LOAN BALANCE: {self.balance_label(loan)}",""])
        lines.extend(["Thank you for your continued patronage.","*_Ⓜ️🅱️ Mr Brownian_*"])
        return "\n".join(lines)

    def bulk_customer_statements(self):
        self._section_key="customers"
        page,body=self.scroll_page("BULK CUSTOMER STATEMENTS")
        body.add_widget(self.section_label("STATEMENT PERIOD"))
        period,start,end=self.period_controls(body)
        period.values=("Today","This Week","Last Week","This Month","Last Month","Custom Range")
        period.text="Last Week"
        now=datetime.now(); week_start=now-timedelta(days=now.weekday()+7)
        start.text=week_start.strftime("%Y-%m-%d")
        end.text=(week_start+timedelta(days=6)).strftime("%Y-%m-%d")
        body.add_widget(self.section_label("CUSTOMER SELECTION"))
        audience=Spinner(text="Transactions or Outstanding",values=("Transactions or Outstanding","All Customers","Transactions Only","Outstanding Only"),size_hint_y=None,height=dp(58))
        body.add_widget(audience)
        body.add_widget(self.section_label("STATEMENT DETAILS"))
        detail=Spinner(text="Full Transaction Details",values=("Full Transaction Details","Summary Only"),size_hint_y=None,height=dp(58))
        body.add_widget(detail)
        body.add_widget(self.section_label("ACCOUNT TYPE"))
        account=Spinner(text="Trading",values=("Trading","Loans & Debts","Combined"),size_hint_y=None,height=dp(58))
        body.add_widget(account)
        body.add_widget(self.section_label("CAMPAIGN TITLE"))
        title=self.style_input(TextInput(text="WEEKLY CUSTOMER STATEMENTS",multiline=False,size_hint_y=None,height=dp(55)))
        body.add_widget(title)
        info=self.section_label("PREVIEW: Select PREPARE to validate recipient statements")
        body.add_widget(info)
        state={"jobs":[],"invalid":[],"signature":None}
        def signature():return (start.text,end.text,audience.text,detail.text,account.text,title.text)
        def prepare(*_):
            a,b=start.text.strip(),end.text.strip()
            try:
                datetime.strptime(a,"%Y-%m-%d");datetime.strptime(b,"%Y-%m-%d")
                if a>b:raise ValueError("Start date is after end date")
            except ValueError as e:return self.popup("INVALID PERIOD",str(e))
            jobs=[];invalid=[];seen=set()
            names=set(self.data.get("customers",{}))
            names.update(str(x.get("customer")) for x in self.data.get("transactions",[]) if x.get("customer"))
            for name in sorted(names):
                transactions=any(x.get("customer")==name and self._date_ok(str(x.get("date","")),a,b) for x in self.data.get("transactions",[]))
                transactions=transactions or any(x.get("customer")==name and self._date_ok(str(x.get("date","")),a,b) for x in self.data.get("customer_payments",[]))
                outstanding=abs(self.customer_trading_balance_asof(name,b))>.004
                if audience.text=="Transactions or Outstanding" and not(transactions or outstanding):continue
                if audience.text=="Transactions Only" and not transactions:continue
                if audience.text=="Outstanding Only" and not outstanding:continue
                rec=self.customer_contact_record(name)
                raw=str(rec.get("whatsapp") or rec.get("phone") or "")
                number=self.normalize_whatsapp_number(raw)
                if not number or not (11<=len(number)<=15):
                    invalid.append({"name":name,"number":raw,"reason":"Missing/invalid WhatsApp"});continue
                if number in seen:
                    invalid.append({"name":name,"number":raw,"reason":"Duplicate WhatsApp number: review identity"});continue
                try:statement=self.periodic_customer_statement_text(name,a,b,detail.text=="Summary Only",account.text)
                except Exception as e:
                    invalid.append({"name":name,"number":raw,"reason":str(e)});continue
                seen.add(number)
                jobs.append({"name":name,"number":number,"status":"pending","statement_text":statement})
            state.update(jobs=jobs,invalid=invalid,signature=signature())
            info.text=f"Ready: {len(jobs)} | Excluded / review: {len(invalid)} | Period: {a} to {b}"
            preview=(jobs[0]["statement_text"][:1800] if jobs else "No eligible customers")
            errors="\n".join(x["name"]+": "+x["reason"] for x in invalid[:12])
            self.popup("STATEMENT PREVIEW",info.text+"\n\n"+preview+("\n\nEXCLUDED:\n"+errors if errors else ""))
        def send(*_):
            if signature()!=state["signature"]:
                return self.popup("PREVIEW REQUIRED","Prepare and review statements after changing settings.")
            if not state["jobs"]:return self.popup("NO RECIPIENTS","No validated statements to send.")
            def approved():
                g=self.data.setdefault("global",{})
                old=g.get("messaging_campaign",{})
                if isinstance(old,dict) and old.get("jobs") and int(old.get("index",0))<len(old.get("jobs",[])) and not old.get("stopped"):
                    return self.popup("ACTIVE CAMPAIGN","Pause/finish the existing campaign before creating another.")
                if isinstance(old,dict) and old.get("jobs"):
                    g.setdefault("messaging_history",[]).append(dict(old))
                g["messaging_campaign"]={"title":title.text.strip() or "Customer Statements", "audience":"Selected Customers", "platform":"POPPO", "selected":[j["name"] for j in state["jobs"]],
                    "body":"Individual customer statements", "mode":"customer_statements", "period_start":start.text,"period_end":end.text,
                    "jobs":list(state["jobs"]),"invalid":list(state["invalid"]),"index":0,"paused":False,"stopped":False,"created":datetime.now().strftime("%Y-%m-%d %H:%M:%S")}
                self.save();self.messaging_hub()
                self.popup("CAMPAIGN READY","Tap SEND / RESUME once to start. Each WhatsApp chat may require manual sending.")
            self.request_pin_action("APPROVE STATEMENT CAMPAIGN",f"Prepare {len(state['jobs'])} private statements for WhatsApp?",approved)
        body.add_widget(self.nav_button("PREPARE / PREVIEW STATEMENTS",prepare,"primary"))
        body.add_widget(self.nav_button("APPROVE & OPEN MESSAGING",send,"success"))
        body.add_widget(self.nav_button("BACK TO MESSAGING",self.messaging_hub,"muted"))
        self.show(page)

    def personalize_campaign_message(self, template, name):
        """Return per-recipient text and unresolved placeholders, without changing records."""
        c=self.customer_contact_record(name) or {}
        identity=self.data.get("customers",{}).get(name,{}) or {}
        name_parts=str(name).strip().split()
        values={
            "FirstName":name_parts[0] if name_parts else "",
            "FullName":str(name).strip(),
            "LastName":" ".join(name_parts[1:]) if len(name_parts)>1 else "",
            "CustomerID":str(identity.get("mbal_id") or ""),
            "WhatsAppNumber":str(c.get("whatsapp") or c.get("phone") or ""),
        }
        platform_ids=self.customer_platform_ids(name)
        # Resolve placeholders against the customer's current platform-ID records.
        # This supports newly added platform names and naturally drops deleted ones.
        for platform, ids in platform_ids.items():
            token=re.sub(r"[^A-Za-z0-9_]","_",str(platform)).strip("_").upper()+"_ID"
            values[token] = ", ".join(map(str,ids))
        unknown=[]
        def substitute(m):
            field=m.group(1)
            value=values.get(field,"")
            if not value:unknown.append(field)
            return value or m.group(0)
        output=re.sub(r"\[([A-Za-z][A-Za-z0-9_]*)\]",substitute,str(template or ""))
        return output,sorted(set(unknown))

    def messaging_select_attachments(self, campaign, refresh_label=None):
        """Choose multiple files for a messaging campaign using Android-visible storage."""
        current=list(campaign.get("attachments",[]) or [])
        # No extension/MIME filter: allow every file type visible to Android storage.
        chooser=FileChooserListView(path="/storage/emulated/0",
                                   multiselect=True, size_hint=(1,1))
        layout=BoxLayout(orientation="vertical", spacing=dp(6), padding=dp(8))
        layout.add_widget(Label(text="Select one or more files (all file types are allowed).",size_hint_y=None,height=dp(38)))
        layout.add_widget(chooser)
        buttons=BoxLayout(size_hint_y=None,height=dp(48),spacing=dp(8))
        popup=Popup(title="ATTACH FILES",content=layout,size_hint=(.96,.90),auto_dismiss=False)
        def apply(*_):
            selected=[os.path.abspath(x) for x in (chooser.selection or []) if os.path.isfile(x)]
            campaign["attachments"]=list(dict.fromkeys(selected))
            self.save()
            if refresh_label:
                refresh_label.text="ATTACHMENTS: "+("; ".join(os.path.basename(x) for x in campaign["attachments"]) if campaign["attachments"] else "None")
            popup.dismiss()
        buttons.add_widget(self.nav_button("USE SELECTED",apply,"success"))
        buttons.add_widget(self.nav_button("CANCEL",popup.dismiss,"muted"))
        layout.add_widget(buttons);popup.open()

    def share_messaging_attachments(self, paths, message_text=""):
        """Open Android share sheet for multiple campaign files and accompanying text."""
        valid=[os.path.abspath(x) for x in (paths or []) if os.path.isfile(x)]
        if not valid:
            self.popup("ATTACHMENTS UNAVAILABLE","The selected file(s) could not be found. Reattach them and try again.")
            return False
        try:
            from jnius import autoclass, cast
            import mimetypes
            Intent=autoclass("android.content.Intent")
            Uri=autoclass("android.net.Uri")
            File=autoclass("java.io.File")
            ArrayList=autoclass("java.util.ArrayList")
            ContentValues=autoclass("android.content.ContentValues")
            # Downloads is a nested Java class; Pyjnius must load it by its
            # binary name rather than looking for MediaStore.Downloads as
            # an attribute on the parent class proxy.
            MediaStoreDownloads=autoclass("android.provider.MediaStore$Downloads")
            BuildVersion=autoclass("android.os.Build$VERSION")
            PythonActivity=autoclass("org.kivy.android.PythonActivity")
            activity=PythonActivity.mActivity
            resolver=activity.getContentResolver()

            # Never expose file:// URIs. Publish each arbitrary file into the
            # app's public Downloads/MrBrownian folder and share its content:// URI.
            # MediaStore insertion works without a manifest FileProvider declaration.
            if int(BuildVersion.SDK_INT) < 29:
                raise RuntimeError("Sharing attachments requires Android 10 or newer on this build.")
            streams=ArrayList()
            published=[]
            for path in valid:
                name=os.path.basename(path)
                mime=mimetypes.guess_type(name)[0] or "application/octet-stream"
                values=ContentValues()
                values.put("_display_name",name)
                values.put("mime_type",mime)
                values.put("relative_path","Download/MrBrownian")
                # Do not set IS_PENDING: Pyjnius cannot reliably select the
                # ContentValues.put(String, Boolean) overload on this device.
                # The URI is shared only after the complete file copy finishes.
                uri=resolver.insert(MediaStoreDownloads.EXTERNAL_CONTENT_URI,values)
                if uri is None:
                    raise RuntimeError("Android could not create a shareable copy of: "+name)
                try:
                    output=resolver.openOutputStream(uri)
                    if output is None:
                        raise RuntimeError("Could not open Android output stream for: "+name)
                    try:
                        # Java NIO copies the original file bytes directly; no
                        # extension/type restrictions and no Python/Java byte-array conversion.
                        nio=autoclass("java.nio.file.Files")
                        nio.copy(File(path).toPath(),output)
                        output.flush()
                    finally:
                        output.close()
                    # Copy is complete before adding this content URI to the
                    # outgoing share intent; no IS_PENDING update is required.
                    streams.add(cast("android.os.Parcelable",uri))
                    published.append(uri)
                except Exception:
                    try:
                        resolver.delete(uri,None,None)
                    except Exception:
                        pass
                    raise

            intent=Intent(Intent.ACTION_SEND_MULTIPLE)
            intent.setType("*/*")
            intent.putParcelableArrayListExtra(Intent.EXTRA_STREAM,streams)
            if message_text:
                intent.putExtra(Intent.EXTRA_TEXT,str(message_text))
            intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION)
            JavaString=autoclass("java.lang.String")
            chooser_title=cast("java.lang.CharSequence",JavaString("Share campaign attachments"))
            chooser=Intent.createChooser(intent,chooser_title)
            activity.startActivity(chooser)
            return True
        except Exception as exc:
            self.popup("ATTACHMENT SHARING FAILED",str(exc))
            return False

