    def tax_valid_sales(self, year=None, month=None):
        """Read-only sales selection for turnover reporting; never alters source transactions."""
        rows=[]
        invalid_states={"cancelled","canceled","reversed","deleted","void","invalid"}
        for t in self.data.get("transactions",[]):
            date=str(t.get("date", ""))
            if year is not None and not date.startswith(str(year)): continue
            if month is not None and date[:7] != f"{int(year):04d}-{int(month):02d}": continue
            if any(t.get(k) for k in ("deleted","cancelled","reversed","void","invalid")): continue
            state=str(t.get("status",t.get("state",""))).strip().casefold()
            if state in invalid_states: continue
            try: amount=float(t.get("sell",0) or 0)
            except (TypeError,ValueError): continue
            if amount <= 0: continue
            rows.append(t)
        return rows

    def tax_settings(self):
        page,body=self.scroll_page("TAX THRESHOLD SETTINGS")
        g=self.data.setdefault("global",{})
        body.add_widget(self.section_label("Annual turnover monitoring threshold (₦)"))
        threshold=self.style_input(TextInput(text=str(g.get("tax_turnover_threshold",50000000)),multiline=False,input_filter="float",size_hint_y=None,height=dp(54)))
        body.add_widget(threshold)
        body.add_widget(self.section_label("Effective date (YYYY-MM-DD)"))
        effective=self.style_input(TextInput(text=datetime.now().strftime("%Y-%m-%d"),multiline=False,size_hint_y=None,height=dp(54)))
        body.add_widget(effective)
        body.add_widget(self.section_label("This is an internal monitoring setting only; it does not determine statutory exemption or tax liability."))
        def save_threshold(*_):
            try:
                value=float(threshold.text)
                datetime.strptime(effective.text,"%Y-%m-%d")
                if value<=0:raise ValueError()
            except Exception:return self.popup("INVALID INPUT","Enter a positive threshold and valid effective date.")
            def commit():
                g["tax_turnover_threshold"]=value
                self.data.setdefault("tax_threshold_history",[]).append({"amount":value,"effective":effective.text,"changed":datetime.now().isoformat()})
                self.audit("change","tax_threshold",str(value));self.save();self.tax_management()
            self.request_pin_action("TAX THRESHOLD","Change the internal turnover monitoring threshold? This does not establish legal tax eligibility.",commit)
        body.add_widget(self.nav_button("SAVE THRESHOLD (PIN)",save_threshold,"success"))
        body.add_widget(self.nav_button("BACK",self.tax_management,"muted"));self.show(page)

    def tax_management(self, selected_year=None):
        page,body=self.scroll_page("TAX MANAGEMENT — ANNUAL REVIEW")
        try: year=int(selected_year or datetime.now().year)
        except Exception: year=datetime.now().year
        all_rows=self.data.get("transactions",[])
        years={datetime.now().year}
        for t in all_rows:
            try: years.add(int(str(t.get("date",""))[:4]))
            except Exception: pass
        year_options=tuple(str(y) for y in sorted(years,reverse=True))
        year_picker=Spinner(text=str(year),values=year_options,size_hint_y=None,height=dp(50))
        body.add_widget(self.section_label("REPORTING YEAR"));body.add_widget(year_picker)
        threshold=float(self.data.setdefault("global",{}).get("tax_turnover_threshold",50000000) or 50000000)
        rows=self.tax_valid_sales(year)
        gross=sum(self.num(t.get("sell",0)) for t in rows)
        pct=100*gross/threshold if threshold>0 else 0
        body.add_widget(self.section_label(f"ANNUAL SALES TURNOVER — {year}"))
        body.add_widget(self.section_label(f"Recorded valid Goods sales: ₦{gross:,.2f}"))
        body.add_widget(self.section_label(f"Monitoring threshold: ₦{threshold:,.2f}"))
        body.add_widget(self.section_label(f"Threshold used: {pct:.2f}% | Remaining: ₦{max(0,threshold-gross):,.2f}"))
        body.add_widget(self.section_label(f"Qualifying recorded sales transactions: {len(rows)}"))
        if pct>=100: warning="MONITORING ALERT: recorded turnover meets or exceeds the configured threshold. Review records and obtain professional tax advice."
        elif pct>=80: warning="MONITORING ALERT: recorded turnover has reached at least 80% of the configured threshold."
        else: warning="Monitoring only: no legal tax status is inferred from this figure."
        body.add_widget(self.section_label(warning))
        body.add_widget(self.section_label("MONTHLY SALES SUMMARY"))
        for m in range(1,13):
            month_rows=self.tax_valid_sales(year,m)
            total=sum(self.num(t.get("sell",0)) for t in month_rows)
            body.add_widget(self.section_label(f"{datetime(year,m,1):%b}: ₦{total:,.2f} | {len(month_rows)} transactions"))
        def change_year(*_): self.tax_management(year_picker.text)
        year_picker.bind(text=lambda *_: change_year())
        def export_turnover(*_):
            filename=f"Mr_Brownian_Tax_Sales_{year}_{datetime.now():%Y%m%d_%H%M%S}.csv"
            path,_=self.report_output_path(filename)
            fields=["date","transaction_id","customer","platform","platform_id","quantity","sell","status"]
            try:
                with open(path,"w",newline="",encoding="utf-8-sig") as out:
                    writer=csv.DictWriter(out,fieldnames=fields,extrasaction="ignore");writer.writeheader()
                    for t in rows:
                        writer.writerow({"date":t.get("date",""),"transaction_id":t.get("record_id",t.get("id","")),"customer":t.get("customer",t.get("customer_name","")),"platform":t.get("platform",""),"platform_id":t.get("platform_id",t.get("id_on_platform","")),"quantity":t.get("qty",t.get("quantity","")),"sell":t.get("sell",0),"status":t.get("status","valid/recorded")})
                self.share_file(path,"text/csv","Share annual tax sales report")
            except Exception as exc:self.popup("EXPORT FAILED",str(exc))
        body.add_widget(self.nav_button("EXPORT ANNUAL SALES DETAILS (CSV)",export_turnover,"success"))
        body.add_widget(self.nav_button("CONFIGURE MONITORING THRESHOLD (PIN)",self.tax_settings,"accent"))
        body.add_widget(self.nav_button("VIEW ACCOUNTING SCHEDULE (READ ONLY)",lambda:self.tax_accounting_review(year),"primary"))
        body.add_widget(self.nav_button("CALCULATE ANNUAL TAX RETURN",self.annual_tax_return_calculator,"purple"))
        body.add_widget(self.nav_button("NIGERIA TAX REFORM REFERENCE",self.tax_reform_guide,"purple"))
        body.add_widget(self.nav_button("BACK TO FINANCE",self.finance_menu,"muted"));self.show(page)


    def asset_register_total(self):
        """Non-cash/inventory assets manually tracked in the asset register; exclude receivables to avoid double counting the live receivables ledger."""
        total = 0.0
        for item in self.data.get("asset_register", []):
            if str(item.get("category", "")).strip().lower() != "receivables":
                try: total += max(0.0, float(item.get("value", 0) or 0))
                except (TypeError, ValueError): pass
        return round(total, 2)

    def comprehensive_asset_total(self):
        """Cash + inventory + live receivables + manually tracked non-receivable assets."""
        return round(self.total_assets() + self.total_receivables() + self.asset_register_total(), 2)

    def asset_register(self):
        page, body = self.scroll_page("ASSET REGISTER — ASSET MANAGEMENT")
        records = self.data.setdefault("asset_register", [])
        cash_inventory = self.total_assets()
        receivables = self.total_receivables()
        tracked = self.asset_register_total()
        body.add_widget(self.turbo_kpi("ESTIMATED ASSET POSITION", f"₦{self.comprehensive_asset_total():,.2f}", "primary", "Cash + inventory + receivables + tracked assets", "📦"))
        body.add_widget(self.tax_readable_label(f"Cash and inventory from existing records: ₦{cash_inventory:,.2f}"))
        body.add_widget(self.tax_readable_label(f"Receivables from Loans & Debts ledger: ₦{receivables:,.2f}"))
        body.add_widget(self.tax_readable_label(f"Manually tracked assets excluding receivables: ₦{tracked:,.2f}"))
        body.add_widget(self.tax_readable_label("Enter the current carrying/estimated value and update it when it changes. Receivables already in Loans & Debts are included automatically; do not enter the same receivable again here. This is an asset register, not a depreciation or statutory valuation calculation."))
        category = Spinner(text="Equipment", values=("Receivables", "Equipment", "Property", "Investments", "Vehicles", "Intangible Assets", "Other Assets"), size_hint_y=None, height=dp(54))
