        value = self.style_input(TextInput(text="", hint_text="Current value (₦)", multiline=False, input_filter="float", size_hint_y=None, height=dp(54)))
        acquired = self.style_input(TextInput(text="", hint_text="Acquisition / record date (optional, YYYY-MM-DD)", multiline=False, size_hint_y=None, height=dp(54)))
        note = self.style_input(TextInput(text="", hint_text="Notes / location / account (optional)", multiline=True, size_hint_y=None, height=dp(80)))
        for label, widget in (("ASSET CATEGORY", category), ("ASSET / REFERENCE", name), ("CURRENT VALUE (₦)", value), ("DATE (OPTIONAL)", acquired), ("NOTES (OPTIONAL)", note)):
            body.add_widget(self.tax_readable_label(label)); body.add_widget(widget)
        def add_asset(*_):
            title = name.text.strip()
            try: amount = float(value.text.strip().replace(",", ""))
            except (TypeError, ValueError): amount = -1
            if not title:
                self.popup("ASSET NAME REQUIRED", "Enter an asset name or reference."); return
            if amount < 0:
                self.popup("INVALID VALUE", "Enter a valid non-negative asset value."); return
            item = {"id": str(uuid.uuid4()), "category": category.text, "name": title, "value": round(amount, 2), "date": acquired.text.strip(), "notes": note.text.strip(), "updated": datetime.now().isoformat()}
            self.data.setdefault("asset_register", []).append(item)
            self.save()
            self.asset_register()
        body.add_widget(self.nav_button("ADD ASSET TO REGISTER", add_asset, "success"))
