    def inventory_summary(self, platform=None):
        ps=[x for x in self.data.get("purchases",[]) if (not platform or x.get("platform")==platform)]
        qty=sum(float(x.get("remaining_qty",0)) for x in ps)
        value=sum(float(x.get("remaining_cost",0)) for x in ps)
        return qty,value,(value/qty if qty else 0)

    def average_daily_sales(self, platform=None):
        tx=[x for x in self.data.get("transactions",[]) if (not platform or x.get("platform")==platform)]
        days={}
        for x in tx:
            d=x.get("date","")[:10]; days[d]=days.get(d,0)+float(x.get("qty",0))
        return sum(days.values())/len(days) if days else 0

    def allocate_stock_cost(self, platform, qty, commit=False):
        remaining=float(qty);cost=0.0
        lots=[x for x in self.data.get("purchases",[]) if x.get("platform")==platform and float(x.get("remaining_qty",0))>0]
        lots.sort(key=lambda x: str(x.get("date", "")))
        available=sum(float(x.get("remaining_qty",0)) for x in lots)
        if available+1e-9<remaining:return None,available
        for lot in lots:
            if remaining<=0:break
            rq=float(lot.get("remaining_qty",0));rc=float(lot.get("remaining_cost",0))
            take=min(rq,remaining);unit=rc/rq if rq else 0;part=take*unit;cost+=part
            if commit:
                lot["remaining_qty"]=rq-take;lot["remaining_cost"]=max(0,rc-part)
            remaining-=take
        return cost,available

    def allocate_stock_cost_lifo(self, platform, qty, commit=False):
        """LIFO valuation using the same landed lot costs (including applicable bank charge, VAT and stamp duty)."""
        remaining=float(qty);cost=0.0
        lots=[x for x in self.data.get("purchases",[]) if x.get("platform")==platform and float(x.get("remaining_qty",0))>0]
        lots=sorted(lots, key=lambda x: str(x.get("date", "")), reverse=True)
        available=sum(float(x.get("remaining_qty",0)) for x in lots)
        if available+1e-9<remaining:return None,available
        for lot in lots:
            if remaining<=0:break
            rq=float(lot.get("remaining_qty",0));rc=float(lot.get("remaining_cost",0))
            take=min(rq,remaining);unit=rc/rq if rq else 0;part=take*unit;cost+=part
            if commit:
                lot["remaining_qty"]=rq-take;lot["remaining_cost"]=max(0,rc-part)
            remaining-=take
        return cost,available

