    def acquisition_receipt_text(self, rec):
        """Detailed acquisition/withdrawal receipt in the standard aligned text style."""
        import textwrap
        typ=str(rec.get("type", "purchase")).strip().lower()
        withdrawal=typ in ("withdrawal", "withdrawal acquisition")
        title="WITHDRAWAL RECEIPT" if withdrawal else "GOODS ACQUISITION RECEIPT"
        dt=str(rec.get("date") or "")
        date=dt[:10] or datetime.now().strftime("%Y-%m-%d")
        rawtime=dt[11:19]
        try: tm=datetime.strptime(rawtime,"%H:%M:%S").strftime("%I:%M %p").lstrip("0")
        except Exception: tm=rawtime or "Time not recorded"
        customer=str(rec.get("customer") or rec.get("customer_name") or "Not applicable")
        q=self.num(rec.get("qty")); gross=self.num(rec.get("payment_amount",rec.get("cost",0)))
        offset=self.num(rec.get("goods_offset")); cash=self.num(rec.get("cash_payment_amount",max(0,gross-offset)))
        charges=self.num(rec.get("payment_charges",rec.get("bank_charge",0)+rec.get("vat",0)+rec.get("stamp_duty",0)))
        landed=self.num(rec.get("cost",gross+charges))
        rows=[("RECEIPT TYPE",title),("RECORD ID",str(rec.get("record_id") or rec.get("transaction_record_id") or "Not recorded")),
              ("DATE",date),("TIME",tm),("PLATFORM",str(rec.get("platform") or "Not recorded")),
              ("QUANTITY ACQUIRED",f"{q:,.0f}"),("GROSS ACQUISITION",f"₦{gross:,.2f}")]
        if withdrawal:
            saved_rate=self.num(rec.get("withdrawal_rate"))
            if saved_rate>0:
                rows.append(("WITHDRAWAL RATE",f"₦{saved_rate:,.2f}/USDT"))
            rows.append(("CUSTOMER",customer))
            rows.append(("OUTSTANDING BALANCE",self.balance_label(self.num(rec.get("reference_balance_at_close")))))
            rows.append(("Goods OFFSET APPLIED",f"₦{offset:,.2f}"))
            excess=self.num(rec.get("customer_trade_credit_created"))
            if excess>0.004: rows.append(("TRADE CREDIT CREATED",f"₦{excess:,.2f}"))
        rows.extend([("CASH PAYMENT",f"₦{cash:,.2f}"),("BANK CHARGES",f"₦{charges:,.2f}")])
        if self.num(rec.get("bank_charge")): rows.append(("BANK CHARGE",f"₦{self.num(rec.get('bank_charge')):,.2f}"))
        if self.num(rec.get("vat")): rows.append(("VAT",f"₦{self.num(rec.get('vat')):,.2f}"))
        if self.num(rec.get("stamp_duty")): rows.append(("STAMP DUTY",f"₦{self.num(rec.get('stamp_duty')):,.2f}"))
        rows.append(("TOTAL LANDED COST",f"₦{landed:,.2f}"))
        width=max(len(k) for k,v in rows)
        lines=["MR BROWNIAN AGENCIES LTD".center(42),"+2349039854892".center(42),"",title.center(42),""]
        lines.extend(f"{k.ljust(width)}  {v}" for k,v in rows)
        lines += ["", "Thank you.".center(42), "M  B  Mr Brownian".center(42)]
        return "```\n"+"\n".join(lines)+"\n```"

