        whatsapp_username = self.style_input(TextInput(multiline=False, hint_text="Username (optional)", size_hint_y=None, height=dp(27)))
        whatsapp_username.font_size = dp(12); whatsapp_username.padding = [dp(6), dp(3), dp(6), dp(3)]
        whatsapp_username.background_normal = ""; whatsapp_username.background_active = ""; whatsapp_username.background_color = get_color_from_hex("#0A192B")
        whatsapp_username.foreground_color = get_color_from_hex("#FFFFFF"); whatsapp_username.cursor_color = self.PRIMARY
        username_row.add_widget(whatsapp_username)
        customer_note = self.style_input(TextInput(multiline=False, hint_text="Customer note (optional)", size_hint_y=None, height=dp(27)))
        customer_note.font_size = dp(12); customer_note.padding = [dp(6), dp(3), dp(6), dp(3)]
        customer_note.background_normal = ""; customer_note.background_active = ""; customer_note.background_color = get_color_from_hex("#0A192B")
        customer_note.foreground_color = get_color_from_hex("#FFFFFF"); customer_note.cursor_color = self.PRIMARY
        username_row.add_widget(customer_note); person.add_widget(username_row)
        suggestions = BoxLayout(orientation="vertical", size_hint_y=None, height=0, spacing=dp(4))
