            payable=rec.get("type") in ("Loan Payable","IOU Payable");kind="expense" if payable else "income";self.add_finance(kind,pr,"Principal Settlement",rec.get("party",""));self.data["finance"][-1].update({"record_id":self.record_id(),"ref_id":rid,"non_profit":True})
