    def coin_inventory_adjustment(self):
        page,body=self.scroll_page("Goods INVENTORY ADJUSTMENT")
        body.add_widget(Label(text="Use this for Goods-only stock movements. These entries do not change cash.",color=self.SUBTEXT,halign="center",size_hint_y=None,height=dp(70),text_size=(Window.width-dp(60),None)))
        movement=Spinner(text="Goods Received",values=("Goods Received","Goods Gifted / Issued Out"),size_hint_y=None,height=dp(58));platform=Spinner(text=("POPPO" if "POPPO" in self.data["platforms"] else self.current_platform or next(iter(self.data["platforms"]))),values=tuple(sorted(self.data["platforms"])),size_hint_y=None,height=dp(58));qty=self.style_input(TextInput(multiline=False,hint_text="Goods quantity",size_hint_y=None,height=dp(58)));value=self.style_input(TextInput(multiline=False,hint_text="Optional acquisition cost/value (₦); 0 if free",text="0",size_hint_y=None,height=dp(58)));source=self.style_input(TextInput(multiline=False,hint_text="Source / person (optional)",size_hint_y=None,height=dp(58)));note=self.style_input(TextInput(multiline=False,hint_text="Reason / note",size_hint_y=None,height=dp(58)))
        for lab,w in [("Movement",movement),("Platform",platform),("Goods Quantity",qty),("Acquisition Cost / Value",value),("Source / Person",source),("Note",note)]:body.add_widget(self.section_label(lab));body.add_widget(w)
        def mode(*_):value.disabled=(movement.text!="Goods Received");value.opacity=1 if not value.disabled else .45
        movement.bind(text=mode);mode()
        def save_adj(*_):
            q=self.num(qty.text);v=self.num(value.text,0)
            if q<=0 or v<0:self.popup("Check Values","Enter a positive Goods quantity and valid value.");return
            rid=self.record_id();now=datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            if movement.text=="Goods Received":
                self.data.setdefault("purchases",[]).append({"record_id":rid,"date":now,"platform":platform.text,"type":"Goods received","qty":q,"cost":v,"remaining_qty":q,"remaining_cost":v,"source":source.text.strip(),"note":note.text.strip()})
                msg=f"{q:,.0f} {platform.text} Goods added. Cash unchanged."
            else:
                co,av=self.allocate_stock_cost(platform.text,q,False)
                if co is None:self.popup("Insufficient Stock",f"{platform.text}: available {av:,.0f} Goods.");return
                co,_=self.allocate_stock_cost(platform.text,q,True)
                self.data.setdefault("goods_adjustments",[]).append({"record_id":rid,"date":now,"platform":platform.text,"type":"Goods gifted","qty":q,"cost":co,"source":source.text.strip(),"note":note.text.strip()})
                msg=f"{q:,.0f} {platform.text} Goods removed. Cash unchanged."
            self.audit("create","goods_inventory",rid);self.save();self.popup("Inventory Updated",msg);self.coin_inventory_adjustment()
        body.add_widget(self.nav_button("Save Goods Inventory Movement",save_adj,"success"))
        body.add_widget(self.nav_button("VIEW / EDIT / DELETE Goods MOVEMENTS",self.transaction_history,"primary"));body.add_widget(self.nav_button("Back to Finance",self.finances,"muted"));self.show(page)

