    def _authorized_financial_activity_editor(self):
        page,body=self.scroll_page("EDIT FINANCIAL ACTIVITIES")
        body.add_widget(Label(text="Tap a saved activity to edit it. Bank-charge components generated by an expense are rebuilt automatically when that expense is saved.",color=self.SUBTEXT,halign="left",valign="middle",size_hint_y=None,height=dp(80),text_size=(Window.width-dp(55),None)))
        records=[x for x in self.data.get("finance",[]) if not x.get("bank_charge_component")]
        records=sorted(records,key=lambda x:str(x.get("date","")),reverse=True)
        filter_box=self.style_input(TextInput(multiline=False,hint_text="Search date, description, amount, category or reference",size_hint_y=None,height=dp(56)))
        body.add_widget(self.section_label("SEARCH FINANCIAL ACTIVITIES"));body.add_widget(filter_box)
        result_box=GridLayout(cols=1,spacing=dp(5),size_hint_y=None)
        result_box.bind(minimum_height=result_box.setter("height"));body.add_widget(result_box)
        activity_buttons=[]
        for rec in records:
            rid=rec.get("record_id")
            txt=f"{str(rec.get('date',''))[:16]}  |  {str(rec.get('kind','')).upper()}  |  {rec.get('category','')}  |  ₦{self.num(rec.get('amount')):,.2f}"
            def edit(rec=rec,rid=rid):
                ep,eb=self.scroll_page("EDIT FINANCIAL ACTIVITY")
                kind=Spinner(text=str(rec.get("kind","expense")).title(),values=("Income","Expense"),size_hint_y=None,height=dp(58))
                cats=list(self.data.get("global",{}).get("financial_classifications",[]) or [])
                defaults=["Staff Salary","Tax","Capital Injection","Rent","Utilities","Transport","Bank Charge","Other Income","Other Expense"]
                for z in defaults:
                    if z not in cats: cats.append(z)
                category=self.style_input(TextInput(text=str(rec.get("category","") or ""),multiline=False,hint_text="Type or reuse a classification",size_hint_y=None,height=dp(58)))
                amount=self.style_input(TextInput(text=str(self.num(rec.get("amount"))),multiline=False,size_hint_y=None,height=dp(58)))
                note=self.style_input(TextInput(text=str(rec.get("note","") or ""),multiline=False,size_hint_y=None,height=dp(58)))
                for lab,w in (("Type",kind),("Classification",category),("Amount",amount),("Note",note)): eb.add_widget(self.section_label(lab));eb.add_widget(w)
                same_bank_edit=CheckBox(active=bool(rec.get("intrabank",False)),size_hint=(None,None),size=(dp(48),dp(48)))
                same_edit_row=BoxLayout(orientation="horizontal",size_hint_y=None,height=dp(52))
                same_edit_row.add_widget(same_bank_edit);same_edit_row.add_widget(self.section_label("SAME BANK — transfer fee waived; applicable stamp duty remains"));eb.add_widget(same_edit_row)
                charge_preview=Label(text="",color=self.TEXT,halign="left",valign="middle",size_hint_y=None,height=dp(110))
                charge_preview.bind(width=lambda w,v:setattr(w,"text_size",(max(dp(150),v-dp(10)),None)))
                eb.add_widget(self.section_label("BANK CHARGES — PREVIEW ONLY"));eb.add_widget(charge_preview)
                def update_charge_preview(*_):
                    a=self.num(amount.text,0)
                    outgoing=kind.text=="Expense" and category.text.strip().lower() not in ("bank charge","vat on bank charge","stamp duty")
                    ch=self.outgoing_payment_charges(a,intrabank=bool(same_bank_edit.active)) if outgoing else {"bank_charge":0,"vat":0,"stamp_duty":0,"total":0}
                    charge_preview.text=(f"Transfer ₦{ch['bank_charge']:,.2f} | VAT ₦{ch['vat']:,.2f} | Stamp ₦{ch['stamp_duty']:,.2f}\n"
                                         f"Bank charges ₦{ch['total']:,.2f} | Total cash outflow ₦{a+ch['total']:,.2f}\n"
                                         "Not saved — preview only")
                amount.bind(text=update_charge_preview);kind.bind(text=update_charge_preview)
                category.bind(text=update_charge_preview);same_bank_edit.bind(active=update_charge_preview)
                update_charge_preview()
                if cats: eb.add_widget(Label(text="Saved classifications: "+" • ".join(cats),color=self.SUBTEXT,size_hint_y=None,height=dp(70),text_size=(Window.width-dp(55),None)))
                def save_edit(*_):
                    if rec.get("ref_id"):
                        return self.popup("SOURCE-LINKED ACTIVITY",
                            "Edit or reverse the original transaction, acquisition or loan instead.")
                    a=self.num(amount.text,-1)
                    if a<0:return self.popup("Check Value","Enter a valid amount.")
                    # remove old generated charges linked to this activity
                    self.data["finance"]=[x for x in self.data.get("finance",[]) if not (rid and x.get("ref_id")==rid and x.get("bank_charge_component"))]
                    previous={k:rec.get(k) for k in ("kind","amount","category","note","intrabank")}
                    rec["kind"]=kind.text.lower();rec["amount"]=a;rec["category"]=category.text.strip() or "Other";rec["note"]=note.text.strip();rec["payment_method"]="Bank" if kind.text=="Expense" else "Cash";rec["base_payment"]=a;rec["intrabank"]=bool(same_bank_edit.active)
                    cats2=self.data.setdefault("global",{}).setdefault("financial_classifications",[])
                    if rec["category"] not in cats2:cats2.append(rec["category"])
                    if kind.text=="Expense" and rec["category"]!="Bank Charge":self.record_outgoing_payment_charges(a,rec["category"]+(f" — {rec['note']}" if rec['note'] else ""),"",rid,False,intrabank=bool(same_bank_edit.active))
                    current={k:rec.get(k) for k in previous}
                    self.audit("update","finance",rid,"Before: "+json.dumps(previous,ensure_ascii=False)+" | After: "+json.dumps(current,ensure_ascii=False));self.save();self.popup("Updated","Financial activity updated.");self.refresh_current(self._authorized_financial_activity_editor)
                def show_audit(*_):
                    events=[e for e in self.data.get("audit",[]) if str(e.get("record_id",""))==str(rid)]
                    lines=[f"{e.get('date','')} | {e.get('action','')} | {e.get('note','')}" for e in events]
                    self.popup("FINANCIAL ACTIVITY AUDIT HISTORY","\n\n".join(lines) or "No recorded modifications for this activity.")
                eb.add_widget(self.nav_button("VIEW AUDIT HISTORY",show_audit,"accent"))
                eb.add_widget(self.nav_button("SAVE CHANGES",save_edit,"success"))
                def delete_financial_activity(*_):
                    # Source-linked entries are accounting consequences of sales,
                    # acquisitions or loans and cannot be independently deleted.
                    if rec.get("ref_id") or str(rec.get("category","")).lower() in (
                        "customer payment","goods purchase","withdrawal acquisition",
                        "loan payment","loan repayment","loan disbursement"):
                        self.popup("Linked Financial Activity",
                            "This entry belongs to another transaction. Reverse or edit the original transaction instead.")
                        return
                    def final_delete():
                        records=self.data.get("finance",[])
                        if rec not in records:return self.popup("Not Found","Activity was already removed.")
                        # Delete any automatically generated bank/VAT/stamp charges
                        # belonging exclusively to the selected manual entry.
                        self.data["finance"]=[r for r in records if r is not rec and not (
                            rid and r.get("ref_id")==rid and r.get("bank_charge_component"))]
                        self.audit("delete","financial_activity",rid or self.record_id(),
                            "User confirmed permanent deletion twice")
                        self.save()
                        self.popup("Financial Activity Deleted","Balances and reports will reflect the remaining ledger entries.")
                        self._authorized_financial_activity_editor()
                    self.ask("DELETE — CONFIRM 1 OF 2",
                        "Delete this selected financial activity and its own bank charges?",
                        lambda:self.ask("DELETE — FINAL CONFIRMATION 2 OF 2",
                            "This permanently changes the cash balance and reports. Proceed?",final_delete))
                eb.add_widget(self.nav_button("DELETE FINANCIAL ACTIVITY",delete_financial_activity,"danger"))
                eb.add_widget(self.nav_button("BACK",self.financial_activity_editor,"muted"));self.show(ep)
            btn=self.nav_button(txt,edit,"primary")
            activity_buttons.append((rec,btn));result_box.add_widget(btn)
        def filter_activities(_widget,query):
            result_box.clear_widgets()
            q=str(query or "").strip().lower()
            for entry,button in activity_buttons:
                hay=" ".join(str(entry.get(k,"")) for k in ("date","kind","category","amount","note","record_id")).lower()
                if not q or q in hay:result_box.add_widget(button)
        filter_box.bind(text=filter_activities)
        body.add_widget(self.nav_button("BACK TO FINANCES",self.finances,"muted"));self.show(page)

    def finances(self):
        page,body=self.scroll_page("FINANCES")
        cash=self.cash_balance();operating_assets=self.total_assets();receivable=self.total_receivables();repayable=self.total_liabilities();net_value=operating_assets+receivable-repayable
        body.add_widget(self.section_label("CURRENT FINANCIAL POSITION"))
