    def _date_ok(self, datestr, start, end):
        d=datestr[:10]
        return (not start or d>=start) and (not end or d<=end)

    def customer_identity(self, name, platform=""):
        ids=self.customer_platform_ids(name)
        if platform:return ", ".join(ids.get(platform,[]))
        if ids:return "; ".join(f"{p}: {', '.join(v)}" for p,v in sorted(ids.items()) if v)
        return ""

    def report_output_path(self, filename):
        # Prefer a normal user-visible Downloads folder. Fall back to app storage.
        candidates=[
            "/storage/emulated/0/Download/Mr Brownian Reports",
            "/sdcard/Download/Mr Brownian Reports",
        ]
        for folder in candidates:
            try:
                os.makedirs(folder,exist_ok=True)
                test=os.path.join(folder,".write_test")
                with open(test,"w") as f:f.write("ok")
                os.remove(test)
                return os.path.join(folder,filename), True
            except Exception:
                pass
        return os.path.join(self.user_data_dir,filename), False

