    def export_contacts(self, platform=None):
        try:
            from openpyxl import Workbook
        except Exception:
            self.popup("Excel Export Unavailable","Install openpyxl in Pydroid3 and restart the app.");return
        def clean(n):
            x=re.sub(r"[^0-9]","",str(n or ""))
            if x.startswith("0") and len(x)>=10:x="234"+x[1:]
            return x
        rows=[];seen=set()
        for name,rec in sorted((self.data.get("customers",{}) or {}).items(),key=lambda z:z[0].lower()):
            if not isinstance(rec,dict):continue
            ids=rec.get("platform_ids") or {}
            if platform and not self._id_list(ids.get(platform)):continue
            num=clean(rec.get("whatsapp") or rec.get("phone"))
            if not num:continue
            key=(name.strip().lower(),num)
            if key in seen:continue
            seen.add(key);rows.append((name,num))
        wb=Workbook();ws=wb.active;ws.title="Contacts"
        for name,num in rows:ws.append([name,num])
        ws.column_dimensions['A'].width=32;ws.column_dimensions['B'].width=20
        tag=platform or "All";fn=f"00_Mr_Brownian_Contacts_{re.sub(r'[^A-Za-z0-9_-]+','_',tag)}_{datetime.now().strftime('%Y%m%d_%H%M%S')}.xlsx";path,public=self.report_output_path(fn);wb.save(path);self.popup("Contacts Exported",f"{len(rows)} contacts exported.\nOnly columns A (Name) and B (Mobile Number) were created.");self.share_file(path)

