    def report_preview(self, report_type, start="", end="", platform="All Platforms", customer="All Customers", balance_mode="debtors"):
        """In-app preview mirrors the selected all-customer or individual-customer report."""
        txt=self.safe_report_text(report_type,start,end,customer,platform,balance_mode)
        txt=txt.replace("*", "").replace("\r\n", "\n").replace("\r", "\n")
        # Screen report output must have no blank space/empty lines at either end.
        lines=[line.rstrip() for line in txt.split("\n")]
        while lines and not lines[0].strip(): lines.pop(0)
        while lines and not lines[-1].strip(): lines.pop()
        return "\n".join(lines)

    def export_report(self, report_type, start="", end="", customer="All Customers", share=False):
        try:
            from openpyxl import Workbook
            from openpyxl.styles import Font, PatternFill, Alignment
            from openpyxl.utils import get_column_letter
            from openpyxl.drawing.image import Image as XLImage
        except Exception:
            self.popup("Excel Export Unavailable","Install the Excel export component (openpyxl) in this Python environment, then restart the app.");return

        wb=Workbook();wb.remove(wb.active)
        _excel_sig_paths=[]
        def excel_signature_file():
            signed=self._dated_signature_image(560,190)
            if signed is None:return None
            import tempfile
            fp=os.path.join(tempfile.gettempdir(),f"mr_brownian_signature_{datetime.now().strftime('%Y%m%d')}.png")
            signed.save(fp,"PNG");_excel_sig_paths.append(fp);return fp
        def money(v):
            try:return round(float(v or 0),2)
            except:return 0.0
        def sheet(name,headers,rows,totals=None,subtitle=None,money_cols=()):
            ws=wb.create_sheet(name[:31]); headers=[str(x).upper() for x in headers]
            final=["S/N"]+headers
            ws.append(["MR BROWNIAN AGENCIES LTD"]);ws.append([(name+" REPORT").upper()])
            ws.append([(subtitle or f"PERIOD: {start or 'BEGINNING'} TO {end or 'CURRENT'}").upper()]);ws.append([]);ws.append(final)
            for n,row in enumerate(rows,1):ws.append([n]+list(row))
            if totals is not None:ws.append([""]+list(totals))
            lastcol=max(1,len(final))
            for r in (1,2,3):
                ws.merge_cells(start_row=r,start_column=1,end_row=r,end_column=lastcol)
                ws.cell(r,1).alignment=Alignment(horizontal="center")
            ws["A1"].font=Font(bold=True,size=16);ws["A2"].font=Font(bold=True,size=15);ws["A3"].font=Font(bold=True,size=12)
            for c in ws[5]:c.font=Font(bold=True,size=12);c.fill=PatternFill("solid",fgColor="D9EAF7");c.alignment=Alignment(horizontal="center")
            if totals is not None:
                for c in ws[ws.max_row]:c.font=Font(bold=True,size=12)
            for mc in money_cols:
                ci=headers.index(mc.upper())+2 if mc.upper() in headers else None
