            sheet("Sales",["Date","Customer","Customer Code","WhatsApp","Quantity Out","Selling Price","Cash In","Vested Coins Redeemed","Outstanding","FIFO Cost","Profit"],rows,totals,money_cols=("Selling Price","Cash In","Vested Coins Redeemed","Outstanding","FIFO Cost","Profit"))
