            subtitle=f"CUSTOMER: {customer} | AS OF: {end or 'CURRENT'}" if customer!="All Customers" else f"ALL CUSTOMERS | AS OF: {end or 'CURRENT'}"
            sheet("Debtors",["Customer","Customer Code","WhatsApp","Trading Debt"],rows,["SUMMARY","","",money(sum(r[3] for r in rows))],subtitle=subtitle,money_cols=("Trading Debt",))
