            sheet("Receivables",["Date","Person Organisation","Phone","Advanced","Outstanding","Due Date","Status"],rows,["SUMMARY","","",money(sum(r[3] for r in rows)),money(sum(r[4] for r in rows)),"",""],money_cols=("Advanced","Outstanding"))
