            sheet("Repayables Liabilities",["Date","Type","Person Organisation","Received","Outstanding","Due Date","Status"],rows,["SUMMARY","","",money(sum(r[3] for r in rows)),money(sum(r[4] for r in rows)),"",""],money_cols=("Received","Outstanding"))
