            sheet("Profit Analysis",["Platform","Transactions","Sales","FIFO Cost","Profit"],rows,["SUMMARY",sum(r[1] for r in rows),money(sum(r[2] for r in rows)),money(sum(r[3] for r in rows)),money(sum(r[4] for r in rows))],money_cols=("Sales","FIFO Cost","Profit"))
