            sheet("Stock Planning",["Platform","Current Stock","Stock Value","Average Unit Cost","Average Daily Sales"],rows,["SUMMARY",sum(r[1] for r in rows),money(sum(r[2] for r in rows)),"",sum(r[4] for r in rows)],money_cols=("Stock Value","Average Unit Cost"))
