            sheet("Customer Appreciation",["Date","Record ID","Period Start","Period End","Category","Rank","Winner","Platform","Destination ID","Qualifying Purchases","Reward Goods","FIFO Cost (Noncash)","Status"],rows,["SUMMARY","",f"REWARD RECORDS: {len(rows)}","","","","","","",money(sum(r[9] for r in rows)),money(sum(r[10] for r in rows)),money(sum(r[11] for r in rows)),""],money_cols=("Qualifying Purchases","Reward Goods","FIFO Cost (Noncash)"))

