    def chart_card(self,title,data,value_key):
        box=self.card(275,self.PANEL);box.add_widget(Label(text=f"[b]{title}[/b]",markup=True,color=self.TEXT,size_hint_y=None,height=dp(38)))
        chart=BoxLayout(size_hint_y=None,height=dp(195),spacing=dp(5),padding=(dp(8),dp(8)))
        vals=[max(0,float(x.get(value_key,0))) for x in data];mx=max(vals) if vals else 1
        for x,val in zip(data,vals):
            col=BoxLayout(orientation="vertical",spacing=dp(3));col.add_widget(BoxLayout(size_hint_y=max(.05,1-(val/mx if mx else 0))))
            bar=BoxLayout(size_hint_y=max(.05,val/mx if mx else .05))
            with bar.canvas.before:Color(*self.GOLD);rect=RoundedRectangle(pos=bar.pos,size=bar.size,radius=[dp(5)])
            bar.bind(pos=lambda o,v,r=rect:setattr(r,"pos",v),size=lambda o,v,r=rect:setattr(r,"size",v));col.add_widget(bar)
            col.add_widget(Label(text=str(x.get("label",""))[-6:],color=self.SUBTEXT,font_size="10sp",size_hint_y=.22));chart.add_widget(col)
        box.add_widget(chart);return box

