    def price_optimizer(self):
        page,body=self.scroll_page("PRICE & MARGIN SIMULATOR")
        body.add_widget(Label(text="Enter any two values and leave the value to calculate blank.",color=self.SUBTEXT,halign="center",size_hint_y=None,height=dp(60)))
        cost=self.style_input(TextInput(multiline=False,input_filter="float",hint_text="Cost price",size_hint_y=None,height=dp(54)))
        sell=self.style_input(TextInput(multiline=False,input_filter="float",hint_text="Sell price",size_hint_y=None,height=dp(54)))
        margin=self.style_input(TextInput(multiline=False,input_filter="float",hint_text="Profit margin %",size_hint_y=None,height=dp(54)))
        for lab,w in [("Cost Price",cost),("Sell Price",sell),("Profit Margin %",margin)]:body.add_widget(self.section_label(lab));body.add_widget(w)
        result=self.nav_button("Result: enter exactly two values",lambda:None,"accent");result.height=dp(110);body.add_widget(result)
        def calc(*_):
            try:
                vals=[cost.text.strip(),sell.text.strip(),margin.text.strip()]
                if sum(bool(x) for x in vals)!=2:result.text="Result: enter exactly two values";return
                if not vals[0]:s=float(vals[1]);m=float(vals[2]);co=s*(1-m/100);ans=f"Cost Price: ₦{co:,.2f}"
                elif not vals[1]:
                    co=float(vals[0]);m=float(vals[2])
                    if m>=100:raise ValueError
                    s=co/(1-m/100);ans=f"Sell Price: ₦{s:,.2f}"
                else:co=float(vals[0]);s=float(vals[1]);m=(s-co)/s*100 if s else 0;ans=f"Profit Margin: {m:.2f}%"
                result.text=f"{ans}\nProfit: ₦{s-co:,.2f}"
            except:result.text="Result: check the two values entered"
        cost.bind(text=calc);sell.bind(text=calc);margin.bind(text=calc)
        body.add_widget(self.section_label("OPTIMUM SELLING PRICE — AUTOMATIC"))
        platform=Spinner(text=("POPPO" if "POPPO" in self.data["platforms"] else self.current_platform or next(iter(self.data["platforms"]))),values=tuple(sorted(self.data["platforms"])),size_hint_y=None,height=dp(54))
        body.add_widget(self.section_label("Platform")); body.add_widget(platform)
        out=self.nav_button("Calculating minimum recommended price…",lambda:None,"success"); out.height=dp(230); body.add_widget(out)
        def calculate_optimum(*_):
            try:
                pn=platform.text; price,q,profit,repl=self.minimum_recommended_price(pn)
                p=self.data["platforms"][pn]; step=1.0
                rows=[]; px=price
                while len(rows)<20:
                    pr=px/q*1_000_000.0-repl
                    if pr>10000+1e-7: break
                    rows.append((px,pr)); px+=step
                lines=[f"MINIMUM / RECOMMENDED: ₦{price:,.2f} per {q:,}",
                       f"Replacement Cost/1M: ₦{repl:,.2f}",
                       f"Profit/1M: ₦{profit:,.2f}",
                       "Acceptable range: ₦4,000–₦10,000 profit/1M"]
                if len(rows)>1:
                    lines.append("Other acceptable prices: " + ", ".join(f"₦{a:,.0f} (₦{b:,.0f})" for a,b in rows[1:7]))
                out.text="\n".join(lines)
            except Exception as e:
                out.text="Recommendation unavailable: "+str(e)
        platform.bind(text=calculate_optimum); calculate_optimum()
        body.add_widget(self.nav_button("Back",self.business_hub,"muted"));self.show(page)

